#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Child {
    int v, d, p;
};

bool processChild(vector<Child>& children, int index, vector<int>& result) {
    if (index >= children.size()) return false;

    result.push_back(index + 1); // 1-based indexing

    int vi = children[index].v;
    for (int i = index + 1; i < children.size(); ++i) {
        children[i].p -= (vi--);
        if (children[i].p < 0) {
            int di = children[i].d;
            for (int j = i + 1; j < children.size(); ++j) {
                children[j].p -= di;
            }
            children.erase(children.begin() + i);
            --i; // Adjust index after erase
            vi = -1; // Stop reducing confidence for this iteration
        }
        if (vi == 0) break; // No more reduction
    }

    // Check for chain reactions after the initial reduction
    int j = index + 1;
    while (j < children.size()) {
        if (children[j].p < 0) {
            int di = children[j].d;
            for (int k = j + 1; k < children.size(); ++k) {
                children[k].p -= di;
            }
            children.erase(children.begin() + j);
        } else {
            ++j;
        }
    }

    return true;
}

int main() {
    int n;
    cin >> n;

    vector<Child> children(n);
    for (auto& child : children) {
        cin >> child.v >> child.d >> child.p;
    }

    vector<int> result;
    int index = 0;
    while (index < children.size()) {
        processChild(children, index, result);
        ++index;
    }

    cout << result.size() << endl;
    for (int id : result) {
        cout << id << " ";
    }
    cout << endl;

    return 0;
}

