double calc(const Point& start, const Point& end, const Point& wind, double v, double t_max, double& t) {
    Point dir = end - start;
    double len = length(dir);
    if (len == 0) return 0.0;

    dir = {dir.x / len, dir.y / len};
    double wd = dot(wind, dir);
    double rem = len - wd * t_max;

    if (rem <= 0) {
