struct Event {
    int x, y1, y2, type; // type 0: vertical, type 1: horizontal
};

bool cmp(const Event& a, const Event& b) {
    return a.x < b.x;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<Event> events;
    events.reserve(2 * n);

    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2;
        std::cin >> x1 >> y1 >> x2 >> y2;

        if (x1 > x2) std::swap(x1, x2);
        if (y1 > y2) std::swap(y1, y2);

        if (x1 == x2) { // vertical
            events.push_back({x1, y1, y2, 0});
            events.push_back({x2 + 1, y1, y2, 0});
        } else { // horizontal
            events.push_back({x1, y1, y2, 1});
            events.push_back({x2 + 1, y1, y2, 1});
        }
    }

    std::sort(events.begin(), events.end(), cmp);

    int result = 0;
    std::vector<std::pair<int, int>> active;

    for (const auto& event : events) {
        if (event.type == 0) { // vertical
            active.push_back({event.y1, event.y2});
            std::sort(active.begin(), active.end());
            int curr_y1 = active[0].first;
            int curr_y2 = active[0].second;
            int temp_result = curr_y2 - curr_y1 + 1;
            result += temp_result;
            std::vector<std::pair<int, int>> new_active;
            new_active.push_back({curr_y1, curr_y2});
            for (int i = 1; i < active.size(); ++i) {
                if (active[i].first <= curr_y2) {
                    curr_y2 = std::max(curr_y2, active[i].second);
                } else {
                    new_active.push_back({active[i].first, active[i].second});
                    temp_result += active[i].second - active[i].first + 1;
                    result += temp_result;
                    curr_y1 = active[i].first;
                    curr_y2 = active[i].second;
                }
            }
            active = new_active;
        } else { // horizontal
            int temp_result = 0;
            std::vector<std::pair<int, int>> new_active;
            for (const auto& seg : active) {
                if (seg.first > event.y2 || seg.second < event.y1) {
                    new_active.push_back(seg);
                } else {
                    temp_result += std::min(seg.second, event.y2) - std::max(seg.first, event.y1) + 1;
                }
            }
            result += temp_result;
            active = new_active;
        }
    }

