using namespace std;

struct Event {
    int x, y1, y2, type;
    Event(int x, int y1, int y2, int type) : x(x), y1(y1), y2(y2), type(type) {}
    bool operator<(const Event &other) const {
        if (x != other.x) return x < other.x;
        return type < other.type;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);
        if (x1 == x2) {
            events.emplace_back(x1, y1, y2, 1);
            events.emplace_back(x2 + 1, y1, y2, -1);
        } else {
            events.emplace_back(x1, y1, y1, 2);
            events.emplace_back(x2 + 1, y1, y1, -2);
            events.emplace_back(x1, y2 + 1, y2 + 1, 2);
            events.emplace_back(x2 + 1, y2 + 1, y2 + 1, -2);
        }
    }

    sort(events.begin(), events.end());

    int ans = 0;
    set<int> activeY;
    int lastX = -INFINITY;
    for (const auto &event : events) {
        if (event.type == 1) {
            activeY.insert(event.y1);
            activeY.insert(event.y2);
        } else if (event.type == -1) {
            activeY.erase(event.y1);
            activeY.erase(event.y2);
        } else if (event.type == 2) {
            activeY.insert(event.y1);
        } else {
            activeY.erase(event.y1);
        }

        if (activeY.empty()) continue;

        int minX = *activeY.begin();
        int maxX = *activeY.rbegin();
        ans += (maxX - minX + 1) * (event.x - lastX);
        lastX = event.x;
    }

    cout << ans << endl;

    return 0;
}

