#include <iostream>
#include <vector>
#include <string>

using namespace std;

long long multiply(long long a, long long b) {
    string sa = to_string(a);
    string sb = to_string(b);
    vector<vector<int>> dp(sa.size() + sb.size(), vector<int>(sa.size() + sb.size(), 0));

    for (int i = sa.size() - 1; i >= 0; --i) {
        for (int j = sb.size() - 1; j >= 0; --j) {
            int mul = (sa[i] - '0') * (sb[j] - '0');
            int carry = 0;
            int idx1 = i + j, idx2 = i + j + 1;
            dp[idx1][idx2] = mul % 10;
            carry = mul / 10;

            if (carry > 0) {
                if (idx1 - 1 >= 0 && idx2 - 1 >= 0) {
                    dp[idx1 - 1][idx2 - 1] += carry;
                } else {
                    dp[idx1 - 1][idx2 - 1] = carry;
                }
            }

            for (int k = 0; k < dp.size(); ++k) {
                for (int col = dp[k].size() - 1; col > 0; --col) {
                    if (dp[k][col] >= 10) {
                        dp[k][col - 1] += dp[k][col] / 10;
                        dp[k][col] %= 10;
                    }
                }
            }
        }
    }

    string res;
    bool leadingZero = true;
    for (int i = 0; i < dp.size(); ++i) {
        for (int j = 0; j < dp[i].size(); ++j) {
            if (leadingZero && dp[i][j] == 0) {
                continue;
            }
            leadingZero = false;
            res += to_string(dp[i][j]);
        }
    }

    if (res.empty()) {
        return 0;
    }

    return stoll(res);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> nums(n);
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        nums[i] = stoll(s);
    }

    long long res = 1;
    for (const auto& num : nums) {
        res = multiply(res, num);
        if (res == 0) {
            break;
        }
    }

    cout << res << endl;

    return 0;
}

