        int cur = (a[i] - '0');
        long long temp = 0;
        int j;
        for (j = b.size() - 1; j >= 0; --j) {
            temp = temp * 10 + cur * (b[j] - '0');
            res = res * 10 + temp % 10;
            temp /= 10;
        }
        res = res * 10 + temp;
        temp = 0;
    }
    return res;
}

string multiply(const string& a, long long b) {
    string res = "";
    long long carry = 0;
    for (int i = a.size() - 1; i >= 0; --i) {
        long long cur = (a[i] - '0') * b + carry;
        res = to_string(cur % 10) + res;
        carry = cur / 10;
    }
    if (carry > 0) res = to_string(carry) + res;
    return res;
}

string removeLeadingZeros(const string& s) {
    string res = s;
    while (res.size() > 1 && res[0] == '0') res.erase(0, 1);
    return res;
}

