    memset(bulbs, false, sizeof(bulbs));
    for (int i = 0; i < n; ++i) {
        int k;
        cin >> k;
        buttons[i].resize(k);
        for (int j = 0; j < k; ++j) {
            cin >> buttons[i][j];
        }
    }

    queue<int> q;
    for (int i = 0; i < n; ++i) {
        q.push(i);
    }

    while (!q.empty()) {
        int btn = q.front();
        q.pop();

        bool updated = false;
        for (int bulb : buttons[btn]) {
            if (!bulbs[bulb]) {
                bulbs[bulb] = true;
                updated = true;
            }
        }

        if (updated) {
            for (int i = 0; i < n; ++i) {
                q.push(i);
            }
            q.pop(); // Remove the current button from the queue
        }
    }

    bool allOn = true;
    for (int i = 1; i <= m; ++i) {
        if (!bulbs[i]) {
            allOn = false;
            break;
        }
    }

    cout << (allOn ? "YES" : "NO") << endl;
