#include <iostream>
#include <map>
#include <vector>

using namespace std;

(map<int, int> make_diagonals(const vector<pair<int, int>>& bishops, int (*diagonal)(int, int))) {
    map<int, int> diagonals;
    for (const auto& bishop : bishops) {
        int diagonal_val = diagonal(bishop.first, bishop.second);
        diagonals[diagonal_val]++;
    }
    return diagonals;
}

long long calculate_attacking_pairs(const map<int, int>& diagonals) {
    long long attacking_pairs = 0;
    for (const auto& diagonal : diagonals) {
        int count = diagonal.second;
        if (count > 1) {
            attacking_pairs += (count * (count - 1)) / 2;
        }
    }
    return attacking_pairs;
}

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> bishops(n);
    for (auto& bishop : bishops) {
        cin >> bishop.first >> bishop.second;
    }

    auto positive_diagonals = make_diagonals(bishops, [](int x, int y) { return x - y; });
    auto negative_diagonals = make_diagonals(bishops, [](int x, int y) { return x + y; });

    long long attacking_pairs = calculate_attacking_pairs(positive_diagonals) + calculate_attacking_pairs(negative_diagonals);

    cout << attacking_pairs << endl;

    return 0;
}

