#include <bits/stdc++.h>
using namespace std;

class RMQ {
private:
    vector<vector<int>> rmq;
    int n;

    int query(int l, int r) {
        int s = __builtin_clz(n - r) + __builtin_clz(l + 1);
        if (s == 0) return -1;
        int len = 1 << (s - 1);
        return max(rmq[s][l], rmq[s][r - len + 1]);
    }

public:
    RMQ(const vector<int>& a, int (*f)(int, int)) {
        n = a.size();
        int msb = __builtin_clz(n);
        rmq.resize(32 - msb, vector<int>(n + 1));
        for (int i = 0; i < n; ++i) rmq[0][i] = a[i];
        for (int s = 1; s < 32 - msb; ++s) {
            int len = 1 << (s - 1);
            for (int i = 0; i + len < n; ++i) {
                rmq[s][i] = f(rmq[s - 1][i], rmq[s - 1][i + len]);
            }
        }
    }
};

int n, m;
vector<int> a;
vector<tuple<int, int, int>> q;

void solve() {
    cin >> n >> m;
    a.resize(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    q.resize(m);
    for (auto& [l, r, x] : q) cin >> l >> r >> x, --l, --r;

    vector<int> ans(m);
    auto get_pos = [&](int val) {
        RMQ rmq(a, [](int x, int y) { return x != y ? x : y; });
        for (int i = 0; i < m; ++i) {
            auto [l, r, x] = q[i];
            int pos = -1;
            int s = __builtin_clz(n - r) + __builtin_clz(l + 1);
            if (s == 0) continue;
            int len = 1 << (s - 1);
            if (rmq.query(l, r) != val) {
                pos = l;
                while (len > 1) {
                    if (rmq.query(pos, pos + len / 2 - 1) != val) {
                        pos += len / 2;
                    }
                    len /= 2;
                }
            }
            ans[i] = pos;
        }
    };

    get_pos(-1); // warm-up
    for (int x = 1; x <= 1e6; ++x) get_pos(x);

    for (int i = 0; i < m; ++i) {
        cout << ans[i] + 1 << '\n';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int t = 1;
    // cin >> t;
    while (t--) solve();
}

