        --qs[i].l; --qs[i].r; qs[i].idx = i;
    }
    sort(qs.begin(), qs.end(), [](const Query& q1, const Query& q2) {
        return q1.r < q2.r;
    });
    vector<int> ans(m);
    int curr_r = -1;
    unordered_map<int, deque<int>> map;
    for (int i = 0; i < n; ++i) {
        map[a[i]].push_back(i);
    }
    for (const auto& q : qs) {
        while (curr_r < q.r) {
            ++curr_r;
            map[a[curr_r]].push_back(curr_r);
        }
        int result = -1;
        if (map.find(q.xi) != map.end()) {
            auto& dq = map[q.xi];
            while (!dq.empty() && dq.front() < q.l) dq.pop_front();
            if (!dq.empty() && dq.front() <= q.r) {
                result = dq.front();
            } else {
                for (auto& p : map) {
                    if (p.first != q.xi) {
                        auto& dq = p.second;
                        while (!dq.empty() && dq.front() < q.l) dq.pop_front();
                        if (!dq.empty() && dq.front() <= q.r) {
