                if (!dq.empty() && dq.front() <= q.r) {
                    result = dq.front();
                    break;
                }
            }
        }
        ans[q.idx] = result;
    }
    for (int i = 0; i < m; ++i) cout << ans[i] << "\n";
    return 0;
}

