#include <vector>
#include <string>
#include <algorithm>

using namespace std;

string reverse_string(const string& s) {
    string res = s;
    reverse(res.begin(), res.end());
    // Remove leading zeros
    while (res.length() > 1 && res[0] == '0') {
        res.erase(0, 1);
    }
    return res;
}

long long string_to_longlong(const string& s) {
    long long res = 0;
    for (char c : s) {
        res = res * 10 + (c - '0');
    }
    return res;
}

bool check(const string& a, long long n) {
    string ar = reverse_string(a);
    long long sum = string_to_longlong(a) + string_to_longlong(ar);
    return sum == n;
}

int main() {
    string n_str;
    getline(cin, n_str);
    long long n = string_to_longlong(n_str);

    // Special case handling for n = 0 (not possible per problem statement)
    if (n == 0) {
        cout << 0 << endl;
        return 0;
    }

    // Generate all possible numbers with up to the same number of digits as n
    int max_digits = n_str.length();
    for (int digits = 1; digits <= max_digits; ++digits) {
        for (int i = 1; i < (1 << digits); ++i) { // Iterate over possible "templates" with leading zeros allowed in template
            string a_template(digits, '0');
            int idx = 0;
            for (int j = digits - 1; j >= 0; --j) {
                if (i & (1 << j)) {
                    a_template[idx] = '1';
                    idx++;
                }
            }
            // Fill the rest with 9s to maximize the value for this template
            while (idx < digits) {
                a_template[idx] = '9';
                idx++;
            }
            // Check all numbers matching the current template
            for (int mask = 0; mask < (1 << digits); ++mask) {
                if (__builtin_popcount(mask) != __builtin_popcount(i)) continue; // Same number of 1s
                string a(digits, '0');
                int pos = 0;
                for (int j = 0; j < digits; ++j) {
                    if (mask & (1 << j)) {
                        a[j] = a_template[pos];
                        pos++;
                    }
                }
                if (a[0] == '0') continue; // No leading zeros
                if (check(a, n)) {
                    cout << a << endl;
                    return 0;
                }
            }
        }
    }

    // If no solution found
    cout << 0 << endl;
    return 0;
}

