struct Event {
    int day;
    int type; // 0: start, 1: end
    Friend friendInfo;
};

bool cmp(const Event& a, const Event& b) {
    if (a.day == b.day) {
        return a.type < b.type;
    }
    return a.day < b.day;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<Friend> friends(n);
    for (int i = 0; i < n; ++i) {
        cin >> friends[i].gender >> friends[i].start >> friends[i].end;
    }

    vector<Event> events;
    for (const auto& friendInfo : friends) {
        events.push_back({friendInfo.start, 0, friendInfo});
        events.push_back({friendInfo.end + 1, 1, friendInfo}); // +1 to handle end day correctly
    }

    sort(events.begin(), events.end(), cmp);

    int maxFriends = 0;
    int currentMale = 0, currentFemale = 0;

    for (const auto& event : events) {
        if (event.type == 0) { // start
            if (event.friendInfo.gender == 'M') {
                currentMale++;
            } else {
                currentFemale++;
            }
            int currentTotal = currentMale + currentFemale;
            if (currentMale == currentFemale) {
                maxFriends = max(maxFriends, currentTotal);
            }
        } else { // end
            if (event.friendInfo.gender == 'M') {
                currentMale--;
            } else {
                currentFemale--;
            }
        }
    }

    cout << maxFriends << endl;

    return 0;
}

