long long LCM(int a, int b) {
    long long hcf = INT_MIN;
    int temp_a = a;
    int temp_b = b;

    while (temp_b != 0) {
        int temp = temp_b;
        temp_b = temp_a % temp_b;
        temp_a = temp;
        if (hcf == INT_MIN || temp_a < hcf)
            hcf = temp_a;
    }

    long long lcm = ((long long)a * b) / hcf;
    return lcm;
}

long long LCMRange(int start, int end) {
    long long lcm = start;
    for (int i = start + 1; i <= end; ++i) {
        lcm = LCM(i, lcm);
    }
    return lcm;
}

int main() {
