#include <string>
#include <sstream>

struct Block {
    int length;
    char c;
};

std::vector<Block> parseBlocks(const std::string& str) {
    std::vector<Block> blocks;
    std::istringstream iss(str);
    std::string token;

    while (std::getline(iss, token, ' ')) {
        size_t pos = token.find('-');
        int length = std::stoi(token.substr(0, pos));
        char c = token[pos + 1];
        blocks.emplace_back(Block{length, c});
    }

    return blocks;
}

int main() {
    int n, m;
    std::cin >> n >> m;

    std::string tStr, sStr;
    std::cin.ignore(); // Ignore newline character
    std::getline(std::cin, tStr);
    std::getline(std::cin, sStr);

    auto t = parseBlocks(tStr);
    auto s = parseBlocks(sStr);

    int64_t totalLengthT = 0;
    for (const auto& block : t) {
        totalLengthT += block.length;
    }

    int64_t totalLengthS = 0;
    for (const auto& block : s) {
        totalLengthS += block.length;
    }

    int64_t pos = 0;
    int count = 0;

    while (pos <= totalLengthT - totalLengthS) {
        int64_t currPos = pos;
        int sIndex = 0;
        int tIndex = 0;
        int64_t tBlockRem = t[0].length;

        while (sIndex < m) {
            if (t[tIndex].c != s[sIndex].c) {
                pos = currPos + 1;
                goto nextIteration;
            }

            int64_t required = s[sIndex].length;
            if (tBlockRem >= required) {
                tBlockRem -= required;
                sIndex++;
            } else {
                required -= tBlockRem;
                tBlockRem = t[++tIndex].length - required;
                if (tBlockRem < 0) {
                    pos = currPos + 1;
                    goto nextIteration;
                }
                sIndex++;
            }
        }

        count++;
        pos = currPos + 1;
nextIteration:
        ;
    }

    std::cout << count << std::endl;

    return 0;
}

