    string blockStr;
    for (auto& block : blocks) {
        iss >> blockStr;
        block.length = stoi(blockStr.substr(0, blockStr.find('-')));
        block.ch = blockStr[blockStr.find('-') + 1];
    }
    return blocks;
}

