    int n, m;
    cin >> n >> m;

    string tLine, sLine;
    cin.ignore(); // Ignore newline left in input buffer
    getline(cin, tLine);
    getline(cin, sLine);

    vector<Block> tBlocks = parseBlocks(n, tLine);
    vector<Block> sBlocks = parseBlocks(m, sLine);

    int sLength = 0;
    for (const auto& block : sBlocks) {
        sLength += block.length;
    }

