    long long total = 0;
    for (const auto& block : blocks) {
        total += block.length;
    }
    return total;
}

long long countOccurrences(const vector<Block>& tBlocks, const vector<Block>& sBlocks) {
    long long tLength = calculateLength(tBlocks);
    long long sLength = calculateLength(sBlocks);

    if (sLength > tLength) {
        return 0;
    }

    long long count = 0;
    for (long long p = 0; p <= tLength - sLength; ++p) {
        bool isMatch = true;
        long long sPos = 0;
        long long tBlockIdx = 0;
