#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

struct Block {
    int length;
    char character;
};

vector<Block> parseBlocks(const string& line) {
    vector<Block> blocks;
    stringstream ss(line);
    string blockStr;
    while (ss >> blockStr) {
        size_t hyphenPos = blockStr.find('-');
        int length = stoi(blockStr.substr(0, hyphenPos));
        char character = blockStr[hyphenPos + 1];
        blocks.push_back({length, character});
    }
    return blocks;
}

int countOccurrences(const vector<Block>& t, const vector<Block>& s) {
    int count = 0;
    int tIndex = 0;
    int tLength = 0;
    for (const auto& block : t) {
        tLength += block.length;
    }

    int sLength = 0;
    for (const auto& block : s) {
        sLength += block.length;
    }

    while (tIndex < t.size() && tLength - sLength >= 0) {
        int sIndex = 0;
        int matchedLength = 0;
        int tBlockIndex = tIndex;
        int tBlockRemaining = t[tBlockIndex].length;

        while (sIndex < s.size() && tBlockIndex < t.size()) {
            const auto& sBlock = s[sIndex];
            const auto& tBlock = t[tBlockIndex];

            if (tBlock.character != sBlock.character) {
                break;
            }

            int minLength = min(tBlockRemaining, sBlock.length);
            matchedLength += minLength;

            if (tBlockRemaining <= sBlock.length) {
                tBlockIndex++;
                if (tBlockIndex < t.size()) {
                    tBlockRemaining = t[tBlockIndex].length;
                }
            } else {
                tBlockRemaining -= minLength;
            }

            if (minLength == sBlock.length) {
                sIndex++;
            } else {
                // Not fully matched, break
                matchedLength = 0;
                break;
            }
        }

        if (matchedLength == sLength) {
            count++;
        }

        // Move to the next possible start position in t
        if (tIndex < t.size()) {
            tLength -= t[tIndex].length;
            tIndex++;
        }
    }

    return count;
}

int main() {
    int n, m;
    cin >> n >> m;
    string tLine, sLine;
    cin.ignore(); // Ignore newline left in input buffer
    getline(cin, tLine);
    getline(cin, sLine);

    vector<Block> t = parseBlocks(tLine);
    vector<Block> s = parseBlocks(sLine);

    cout << countOccurrences(t, s) << endl;

    return 0;
}

