// Function to calculate the year based on the given suffix
long long calculate_year(const string& suffix) {
    long long year = 1989; // starting year
    int len = suffix.length();

    // Map to store the used suffixes and their corresponding years
    unordered_map<string, long long> used_suffixes;
    used_suffixes["9"] = 1989;
    used_suffixes["0"] = 1990;
    used_suffixes["1"] = 1991;

    // Generate used suffixes up to the required length
    for (int l = 1; l <= 9; ++l) {
        string curr_suffix;
        for (int i = 0; i < l; ++i) {
            curr_suffix += '0';
        }
        long long curr_year = 1989;
        for (int i = 0; i < l; ++i) {
            curr_year = curr_year * 10;
            if (curr_year > 9999999999) break; // year limit
            used_suffixes[curr_suffix] = curr_year;
            curr_suffix[i] = '9';
        }
    }

    // Find the year for the given suffix
    if (used_suffixes.find(suffix) != used_suffixes.end()) {
        year = used_suffixes[suffix];
    } else {
        // If the suffix is not found, calculate it
        string curr_suffix = suffix;
        year = 1989;
