using namespace std;

struct Token {
    enum Type { NUMBER, OPERATION, QUESTION_MARK } type;
    int value;
};

struct Rebus {
    vector<Token> tokens;
    int n;
};

Rebus parseRebus(const string& input) {
    Rebus rebus;
    istringstream iss(input);
    string tokenStr;

    while (iss >> tokenStr) {
        if (tokenStr == "?") {
            rebus.tokens.push_back({Token::Type::QUESTION_MARK, 0});
        } else if (tokenStr == "+" || tokenStr == "-") {
            rebus.tokens.push_back({Token::Type::OPERATION, tokenStr[0]});
        } else if (tokenStr == "=") {
            rebus.tokens.push_back({Token::Type::OPERATION, '='});
        } else {
            rebus.n = stoi(tokenStr);
        }
    }

    return rebus;
}

pair<bool, vector<int>> solveRebus(const Rebus& rebus) {
    int plusCount = 0, minusCount = 0;
    for (const auto& token : rebus.tokens) {
        if (token.type == Token::Type::OPERATION) {
            if (token.value == '+') plusCount++;
            else if (token.value == '-') minusCount++;
        }
    }
    plusCount++; // Initial ?

    vector<int> values(plusCount + minusCount, 0); // Array to store values for question marks

    // Set up initial constraints
    int totalPlus = 0, totalMinus = 0;
    for (int i = 0; i < plusCount; ++i) totalPlus += 1; // Minimum value for '+ ?'
    for (int i = 0; i < minusCount; ++i) totalMinus += 1; // Minimum value for '- ?'

    if (totalPlus - totalMinus > rebus.n) return {false, {}};
    if (totalPlus - totalMinus == rebus.n) {
        // If sum equals n exactly with minimum values, return this solution
        for (int i = 0; i < plusCount; ++i) values[i] = 1;
        for (int i = plusCount; i < plusCount + minusCount; ++i) values[i] = 1;
        return {true, values};
    }

    int diff = rebus.n - (totalPlus - totalMinus);
    if (diff < 0) return {false, {}}; // Not possible if difference is negative

    // Distribute the difference to the '+' terms first to maximize the value
    for (int i = 0; i < plusCount && diff > 0; ++i) {
        int canAdd = min(diff, rebus.n - values[i]); // Ensure value doesn't exceed n
        values[i] += canAdd;
        diff -= canAdd;
    }

    // If there's still difference left, distribute to '-' terms (though this would decrease total, so it's not ideal but we do it for completeness)
    for (int i = plusCount; i < plusCount + minusCount && diff > 0; ++i) {
        int canAdd = min(diff, rebus.n - values[i]);
        values[i] += canAdd;
        diff -= canAdd;
    }

    if (diff != 0) return {false, {}}; // Failed to distribute all difference

    return {true, values};
}

string reconstructRebus(const Rebus& rebus, const vector<int>& values) {
    string reconstructed;
    int valueIndex = 0;
    for (const auto& token : rebus.tokens) {
        if (token.type == Token::Type::QUESTION_MARK) {
            reconstructed += to_string(values[valueIndex++]);
