    if (!aBottles.empty()) res -= dist(a, t); // If Adil has bottles, subtract initial trip
    for (const auto& p : aBottles) res += costA(p);

    res += dist(b, t); // Bera goes to bin initially
    if (!bBottles.empty()) res -= dist(b, t); // If Bera has bottles, subtract initial trip
    for (const auto& p : bBottles) res += costB(p);

    return res;
}

