pair<ll, ll> solve(ll x) {
    ll cnt = 0;
    while(x > 0) {
        ll a = (ll)cbrt(x);
        cnt++;
        x -= a * a * a;
    }
    return {cnt, x + cnt * cnt * cnt};
}

