class UnionFind {
public:
    vector<int> parent;
    UnionFind(int n) : parent(n, -1) {}
    int root(int x) {
        if (parent[x] < 0) return x;
        parent[x] = root(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (parent[x] < parent[y]) swap(x, y);
        parent[x] += parent[y];
        parent[y] = x;
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int size(int x) {
