    int length = 2;
    int count = 0;
    while (true) {
        int max_count = 9 * pow(10, (length / 2) - 1);
        if (count + max_count >= n) {
            return generate_palindrome(length, n - count - 1);
        }
        count += max_count;
        length += 2;
    }
}

