#include <iostream>
#include <string>

void gen_palindromes(std::string& res, unsigned long long n) {
    if (n <= 9) {
        res = std::to_string(n);
        res += res;
        return;
    }

    unsigned long long num = n - 9;
    int length = 6;

    while (num >= (1ULL << (length - 2))) {
        length += 2;
    }

    std::string first_part;
    unsigned long long val = num;
    for (int i = length - 3; i >= 0; --i) {
        first_part += '0' + (val >> i & 1);
    }

    first_part = std::to_string(val & ((1ULL << (length - 2)) - 1)) + first_part;

    res = first_part;
    std::reverse(res.begin(), res.end());
    res = first_part + res;
}

int main() {
    unsigned long long n;
    std::cin >> n;

    std::string res;
    gen_palindromes(res, n);

    std::cout << res << std::endl;
    return 0;
}

