using namespace std;

void test() {
    int n;
    cin >> n;
    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
    }

    int root = -1;
    for (int i = 0; i < n; ++i) {
        if (p[i] == i + 1) {
            if (root != -1) {
                root = -1; // multiple roots
                break;
            }
            root = i + 1;
        }
    }

    if (root != -1) { // already valid
        cout << 0 << endl;
        for (int i = 0; i < n; ++i) {
            cout << p[i] << " ";
        }
        cout << endl;
        return;
    }

    // fix to have one root
    vector<int> changed(n, 0);
    int changes = 0;
    for (int i = 0; i < n; ++i) {
        if (p[i] == i + 1) {
            changes += 1;
            p[i] = n; // temporary
            changed[i] = 1;
        }
    }

    if (changes == 0) { // no roots, add one
        changes += 1;
        p[0] = 1;
        changed[0] = 1;
        root = 1;
    } else { // multiple roots, make one and change others
        root = n;
        for (int i = 0; i < n; ++i) {
            if (p[i] == i + 1) {
                if (changes < n - 1) { // can still change
                    p[i] = root;
                    changes += 1;
                    changed[i] = 1;
                } else {
                    // cannot change more, pick one as root
                    root = i + 1;
                    p[i] = i + 1;
                    changed[i] = 0; // revert
                    changes -= 1;
                    break;
                }
            }
        }
    }

    // Now ensure the tree is connected (a tree)
    // This is always possible by making all unrooted nodes point to root
    for (int i = 0; i < n; ++i) {
        if (p[i] != root && p[i] != i + 1) {
            if (!changed[i]) { // not changed before
                changes += 1;
                changed[i] = 1;
            }
            p[i] = root;
        }
    }

    cout << changes << endl;
    for (int i = 0; i < n; ++i) {
        cout << p[i] << " ";
    }
    cout << endl;
}

int main() {
    test();
    return 0;
}

