using namespace std;

struct DSU {
    vector<int> parent, rank, size;
    DSU(int n) {
        parent.resize(n);
        rank.resize(n);
        size.resize(n, 1);
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }
    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }
    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        parent[y] = x;
        size[x] += size[y];
        if (rank[x] == rank[y]) rank[x]++;
        return true;
    }
    int getSize(int x) {
        return size[find(x)];
