    cin >> s;

    int count = 0;
    for (int i = 0; i < n; i++) {
        if (fallLeft(n, s, i) || fallRight(n, s, i)) {
            count++;
        }
    }

    cout << count << endl;
    return 0;
}

bool fallLeft(int n, string s, int pos) {
    int curr = pos;
    while (curr > 0 && s[curr] == '<') {
        curr--;
    }
    if (curr == 0) {
        return true;
    }
    if (s[curr] == '<') {
        return false;
    }
    while (curr < n - 1 && s[curr] == '>') {
        curr++;
    }
    if (curr == n - 1) {
        return true;
    }
    return fallLeft(n, s, curr);
}

bool fallRight(int n, string s, int pos) {
    int curr = pos;
    while (curr < n - 1 && s[curr] == '>') {
        curr++;
    }
    if (curr == n - 1) {
        return true;
    }
    if (s[curr] == '>') {
        return false;
    }
    while (curr > 0 && s[curr] == '<') {
        curr--;
    }
    if (curr == 0) {
        return true;
    }
    return fallRight(n, s, curr);
}

