    }

    vector<int> in_degree(n + 1, 0); // To track invalid reports due to hierarchy
    for (int i = 1; i <= n; ++i) {
        if (i == s) continue; // Chief has no superior
        if (a[i] == 0) { // Invalid report: cannot have 0 superiors if not the chief
            ++ans;
            --a[i]; // Correct to -1 to mark as corrected in the hierarchy check
        }
        in_degree[a[i]] += 1; // Track how many report this depth
    }

    int expected = -1; // Expected depth for next valid set of reports
    for (int depth = 0; depth < n; ++depth) {
        if (in_degree[depth] > 0) {
            if (expected == -1) expected = depth;
            else { // Gap in hierarchy, some reports are invalid
                ++ans;
                --in_degree[depth]; // One incorrect report at this depth
                in_degree[expected] += 1; // Corrected report at expected depth
            }
            --in_degree[depth]; // Account for one valid report at this depth
            ++expected; // Next expected depth
        }
    }

    // Remaining in_degree[depth] > 0 indicates invalid reports
    for (int depth = 0; depth < n; ++depth) {
        ans += in_degree[depth];
