int main() {
    int n, s;
    cin >> n >> s;
    --s; // 0-based index

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int mistakes = 0;

    // Check chief's report
    if (a[s] != 0) {
        ++mistakes;
        a[s] = 0; // Correct chief's report
    }

    vector<int> parent(n, -1); // Initialize parent array
    parent[s] = -1; // Chief has no parent

    for (int i = 0; i < n; ++i) {
        if (i == s) continue; // Skip chief

        if (a[i] == 0) { // If reported 0 superiors
            parent[i] = s; // Directly under chief
            ++a[i]; // Correct report to 1 superior (the chief)
        } else if (a[i] > n - 1) { // If reported more superiors than possible
            ++mistakes;
            a[i] = n - 1; // Correct to maximum possible superiors
        }
    }

    // Sort workers by their reported superiors in descending order
    vector<pair<int, int>> sortedWorkers;
    for (int i = 0; i < n; ++i) {
        if (i == s) continue;
        sortedWorkers.emplace_back(a[i], i);
    }
    sort(sortedWorkers.rbegin(), sortedWorkers.rend());

    // Assign parents based on sorted order
    for (const auto& [reported, worker] : sortedWorkers) {
        if (parent[worker] != -1) continue; // Already assigned

        // Find a suitable parent
        for (int superior = n - 1; superior >= 0; --superior) {
            if (superior == worker) continue; // Cannot be own parent
            if (parent[superior] == -1) { // If superior is the chief
                if (reported == 1) { // Worker should be directly under chief
                    parent[worker] = superior;
                    break;
                }
            } else if (a[superior] < reported) { // Superior's depth is less
                ++mistakes;
                a[superior] = reported; // Correct superior's depth
            } else if (a[superior] == reported - 1) { // Superior's depth is one less
                parent[worker] = superior;
                break;
            }
        }

        // If no suitable parent found, worker's report is incorrect
        if (parent[worker] == -1) {
            ++mistakes;
        }
    }

    cout << mistakes << endl;

    return 0;
}

