#include <queue>
#include <algorithm>

using namespace std;

typedef long long ll;

const int N = 3000 + 10;

int n, p, s;
int a[N], b[N];
vector<int> prog, sport;

struct Student {
    int a, b, idx;
    bool operator < (const Student &other) const {
        if (a + b == other.a + other.b) return idx < other.idx;
        return a + b < other.a + other.b;
    }
};

Student students[N];

ll dp[N][N][N];
vector<vector<vector<int>>> from(N, vector<vector<int>>(N, vector<int>(N)));

ll knapSack(int idx, int pLeft, int sLeft) {
    if (pLeft < 0 || sLeft < 0) return -1e18;
    if (idx == n) return 0;

    if (dp[idx][pLeft][sLeft] != -1) return dp[idx][pLeft][sLeft];

    ll takeP = -1e18, takeS = -1e18, takeNeither = -1e18;

    if (pLeft > 0) {
        takeP = students[idx].a + knapSack(idx + 1, pLeft - 1, sLeft);
        if (takeP >= takeNeither) {
            from[idx][pLeft][sLeft] = 1; // takeP
            takeNeither = takeP;
        }
    }

    if (sLeft > 0) {
        takeS = students[idx].b + knapSack(idx + 1, pLeft, sLeft - 1);
        if (takeS >= takeNeither) {
            from[idx][pLeft][sLeft] = 2; // takeS
            takeNeither = takeS;
        }
    }

    takeNeither = knapSack(idx + 1, pLeft, sLeft);
    if (takeNeither >= takeP && takeNeither >= takeS) {
        from[idx][pLeft][sLeft] = 3; // takeNeither
    } else if (takeP >= takeS) {
        from[idx][pLeft][sLeft] = 1; // takeP
    } else {
        from[idx][pLeft][sLeft] = 2; // takeS
    }

    return dp[idx][pLeft][sLeft] = max(max(takeP, takeS), takeNeither);
}

void traceBack(int idx, int pLeft, int sLeft) {
    if (idx == n) return;

    int choice = from[idx][pLeft][sLeft];

    if (choice == 1) { // takeP
        prog.push_back(students[idx].idx);
        traceBack(idx + 1, pLeft - 1, sLeft);
    } else if (choice == 2) { // takeS
        sport.push_back(students[idx].idx);
        traceBack(idx + 1, pLeft, sLeft - 1);
    } else { // takeNeither
        traceBack(idx + 1, pLeft, sLeft);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> p >> s;

    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];

    for (int i = 0; i < n; i++) {
        students[i] = {a[i], b[i], i + 1};
