#include <bits/stdc++.h>

using namespace std;

long long maxHappiness;

void backtrack(vector<bool>& chosen, const vector<pair<int, int>>& subarrays, const vector<int>& flowers, int index, long long currentHappiness) {
    if (index == subarrays.size()) {
        maxHappiness = max(maxHappiness, currentHappiness);
        return;
    }

    // Choose the current subarray
    chosen[index] = true;
    long long newHappiness = currentHappiness;
    for (int i = subarrays[index].first - 1; i < subarrays[index].second; ++i) {
        newHappiness += flowers[i];
    }
    backtrack(chosen, subarrays, flowers, index + 1, newHappiness);
    chosen[index] = false;
    newHappiness = currentHappiness;

    // Don't choose the current subarray
    backtrack(chosen, subarrays, flowers, index + 1, newHappiness);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> flowers(n);
    for (int i = 0; i < n; ++i) {
        cin >> flowers[i];
    }

    vector<pair<int, int>> subarrays(m);
    for (int i = 0; i < m; ++i) {
        cin >> subarrays[i].first >> subarrays[i].second;
    }

    maxHappiness = 0;
    vector<bool> chosen(m, false);
    backtrack(chosen, subarrays, flowers, 0, 0LL);

    cout << maxHappiness << endl;

    return 0;
}

