#include <iostream>
#include <vector>

using namespace std;

class Solution {
public:
    int n;
    vector<int> crush;
    vector<bool> visited;
    vector<int> cycle;

    void dfs(int u, int p, int depth) {
        visited[u] = true;
        cycle.push_back(u);
        if (crush[u] == p) {
            return;
        }
        if (visited[crush[u]]) {
            return;
        }
        dfs(crush[u], u, depth + 1);
    }

    bool is_valid(int t) {
        bool valid = true;
        for (int i = 0; i < n; i++) {
            int start = i;
            int cur = start;
            int cnt = 0;
            while (cnt < t) {
                cur = crush[cur];
                cnt += 1;
                if (cur == start) {
                    break;
                }
            }
            if (cur == start && cnt == t) {
                continue;
            }
            int start2 = cur;
            cur = start2;
            cnt = 0;
            while (cnt < t) {
                cur = crush[cur];
                cnt += 1;
                if (cur == start2) {
                    break;
                }
            }
            if (cur != start) {
                valid = false;
                break;
            }
        }
        return valid;
    }

    int solve() {
        visited.assign(n, false);
        vector<vector<int>> cycles;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                cycle.clear();
                dfs(i, -1, 0);
                cycles.push_back(cycle);
            }
        }
        int ans = 1;
        while (true) {
            if (is_valid(ans)) {
                return ans;
            }
            ans += 1;
            if (ans > 100) {
                return -1;
            }
        }
    }
};

int main() {
