    vector<int> crush(n);
    for (int i = 0; i < n; ++i) {
        cin >> crush[i];
        --crush[i]; // 0-based indexing
    }

    const int max_t = n + 1;
    vector<vector<int>> paths(max_t, vector<int>(n, -1));

    for (int i = 0; i < n; ++i) {
        int current = i;
        int t = 0;
        while (t < max_t && paths[t][current] != i) {
            paths[t][current] = i;
            current = crush[current];
            ++t;
        }
        if (t < max_t && paths[t][current] == i) {
            // Cycle detected, update paths for the cycle
            int cycle_start = paths[t][current];
            int cycle_length = t - paths[t][current];
            for (int k = cycle_start; k < cycle_start + cycle_length; ++k) {
                int pos = (k - cycle_start) % cycle_length + cycle_start;
                for (int tt = 1; tt <= cycle_length; ++tt) {
                    int target = (pos - tt + cycle_length) % cycle_length + cycle_start;
                    paths[tt][pos] = target;
                }
            }
        }
    }

    int min_t = -1;
    for (int t = 1; t <= max_t; ++t) {
        bool valid = true;
        for (int i = 0; i < n && valid; ++i) {
            int joon_joon = i;
            for (int _ = 0; _ < t; ++_) {
                joon_joon = crush[joon_joon];
            }
            int reverse_joon_joon = paths[t][joon_joon];
            if (reverse_joon_joon != i) {
                valid = false;
            }
        }
        if (valid) {
            min_t = t;
            break;
        }
    }

