#include <iostream>
#include <vector>
#include <set>
#include <algorithm>

using namespace std;

const int MX = 500;

struct Coord {
    int x, y;
    Coord(int x = 0, int y = 0) : x(x), y(y) {}
    bool operator<(const Coord& other) const {
        if (x != other.x) return x < other.x;
        return y < other.y;
    }
};

int n, m;
vector<string> grid;
set<Coord> coords;

void readInput() {
    cin >> n >> m;
    grid.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'X') {
                coords.insert(Coord(i, j));
            }
        }
    }
}

bool checkRect() {
    int left = m, right = 0, top = n, bottom = 0;
    for (const auto& coord : coords) {
        left = min(left, coord.y);
        right = max(right, coord.y);
        top = min(top, coord.x);
        bottom = max(bottom, coord.x);
    }
    int w = right - left + 1, h = bottom - top + 1;
    set<Coord> rectCoords;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            rectCoords.insert(Coord(top + i, left + j));
        }
    }
    if (coords == rectCoords) return true;
    return false;
}

bool checkMatch() {
    for (const auto& coord : coords) {
        Coord mirror(coord.x, 2 * m - 1 - coord.y);
        if (coords.find(mirror) == coords.end()) return false;
    }
    return true;
}

void solve() {
    if (!checkRect()) {
        cout << "NO" << endl;
        return;
    }
    if (checkMatch()) {
        cout << "YES" << endl;
        return;
    }
    // Check horizontal and vertical shift
    int minX = *min_element(coords.begin(), coords.end(), [](const Coord& a, const Coord& b) { return a.y < b.y; })->y;
    int maxX = *max_element(coords.begin(), coords.end(), [](const Coord& a, const Coord& b) { return a.y < b.y; })->y;
    int minY = *min_element(coords.begin(), coords.end(), [](const Coord& a, const Coord& b) { return a.x < b.x; })->x;
    int maxY = *max_element(coords.begin(), coords.end(), [](const Coord& a, const Coord& b) { return a.x < b.x; })->x;
    if (maxX - minX + 1 == m && maxY - minY + 1 == n) {
        cout << "YES" << endl;
        return;
    }
    // Check other shifts
    set<Coord> shifted;
    for (const auto& coord : coords) {
        shifted.insert(Coord(coord.x, coord.y + 1));
    }
    bool valid = true;
    for (const auto& coord : shifted) {
        if (coord.y >= m || coords.find(coord) != coords.end()) {
            valid = false;
            break;
        }
    }
    if (valid) {
        cout << "YES" << endl;
        return;
    }
    shifted.clear();
    for (const auto& coord : coords) {
        shifted.insert(Coord(coord.x + 1, coord.y));
    }
    valid = true;
    for (const auto& coord : shifted) {
        if (coord.x >= n || coords.find(coord) != coords.end()) {
            valid = false;
            break;
        }
    }
    if (valid) {
        cout << "YES" << endl;
        return;
    }
    cout << "NO" << endl;
}

int main() {
    readInput();
    solve();
    return 0;
}

