    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        for (int j = 0; j < m; j++) {
            grid[i][j] = s[j];
            if (s[j] == 'X') {
                if (minp.x == 0 || i < minp.x) minp.x = i;
                if (minp.y == 0 || j < minp.y) minp.y = j;
                if (maxp.x == 0 || i > maxp.x) maxp.x = i;
                if (maxp.y == 0 || j > maxp.y) maxp.y = j;
            }
        }
    }

    int w = maxp.x - minp.x + 1;
    int h = maxp.y - minp.y + 1;

    vector<vector<char>> rect(w, vector<char>(h * 2, '.'));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == 'X') {
                int x = i - minp.x;
                int y = j - minp.y;
                rect[x][y] = 'X';
                rect[x][y + h] = 'X';
            }
        }
    }

