    for (int i = 0; i < w; i++) {
        for (int j = 0; j < h * 2; j++) {
            if (rect[i][j] == 'X') {
                if (i == 0 || rect[i-1][j] == '.') valid = false;
                if (i == w-1 || rect[i+1][j] == '.') valid = false;
                if (j == 0 || rect[i][j-1] == '.') valid = false;
                if (j == h*2-1 || rect[i][j+1] == '.') valid = false;
            }
        }
    }

    cout << (valid ? "YES" : "NO") << endl;
