bool check(vector<string>& grid, vector<string>& other, int x, int y) {
    int n = grid.size(), m = grid[0].size();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'X') {
                int nx = x + i, ny = y + j;
                if (!valid(nx, ny, n, m) || other[nx][ny] == 'X') {
                    return false;
                }
            }
        }
    }
    return true;
}

bool place(vector<string>& grid, vector<string>& other, int x, int y) {
    int n = grid.size(), m = grid[0].size();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'X') {
                int nx = x + i, ny = y + j;
                other[nx][ny] = 'X';
            }
        }
    }
    return true;
}

bool is_rect(vector<string>& other) {
    int n = other.size(), m = other[0].size();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (other[i][j] != 'X') {
                return false;
            }
        }
    }
    return true;
}

