bool canFormRectangle(const vector<string>& piece) {
    int n = piece.size();
    int m = piece[0].size();
    vector<vector<bool>> visited(n, vector<bool>(m, false));
    vector<pair<int, int>> edges;
    pair<int, int> start;
    bool foundStart = false;

    // Find the starting 'X' and mark all 'X's as visited
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (piece[i][j] == 'X') {
                if (!foundStart) {
                    start = {i, j};
                    foundStart = true;
                }
                visited[i][j] = true;
            }
        }
    }

    // Perform DFS to find edges (unvisited neighbors of 'X's)
    vector<pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    function<void(int, int)> dfs = [&](int x, int y) {
        for (const auto& dir : directions) {
            int nx = x + dir.first;
            int ny = y + dir.second;
            if (nx < 0 || nx >= n || ny < 0 || ny >= m || piece[nx][ny] != 'X' || visited[nx][ny]) {
                continue;
            }
            visited[nx][ny] = true;
            dfs(nx, ny);
        }
        // Check for edges (neighbors that are not 'X')
        for (const auto& dir : directions) {
            int nx = x + dir.first;
            int ny = y + dir.second;
            if (nx < 0 || nx >= n || ny < 0 || ny >= m || piece[nx][ny] == 'X') {
                continue;
            }
            edges.push_back({nx, ny});
        }
    };
    dfs(start.first, start.second);

    // Check if the number of edges is even and they can form a rectangle
    if (edges.size() % 2 != 0) {
        return false;
    }
    sort(edges.begin(), edges.end());
    for (int i = 0; i < edges.size(); i += 2) {
        if (edges[i] != edges[i + 1]) {
            return false;
        }
    }
    return true;
}

