using namespace std;

int n, m;
vector<string> grid;

void readInput() {
    cin >> n >> m;
    grid.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }
}

pair<int, int> getMin() {
    int minX = m, minY = n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == 'X') {
                minX = min(minX, j);
                minY = min(minY, i);
            }
        }
    }
    return {minX, minY};
}

pair<int, int> getMax() {
    int maxX = -1, maxY = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == 'X') {
                maxX = max(maxX, j);
                maxY = max(maxY, i);
            }
        }
    }
    return {maxX, maxY};
}

bool canFitRight(pair<int, int> minOther, pair<int, int> maxOther) {
    pair<int, int> minOrig, maxOrig;
    minOrig = getMin();
    maxOrig = getMax();
    for (int i = minOther.first; i <= maxOther.first; i++) {
        for (int j = minOther.second; j <= maxOther.second; j++) {
            int origX = i - minOrig.first + maxOrig.first + 1;
            int origY = j - minOrig.second + maxOrig.second + 1;
            if (origX < 0 || origX >= m || origY < 0 || origY >= n) {
                continue;
            }
            if (grid[origY][origX] == 'X') {
                return false;
            }
        }
    }
    return true;
}

bool solve() {
    pair<int, int> minOrig, maxOrig;
    minOrig = getMin();
    maxOrig = getMax();
    if ((maxOrig.first - minOrig.first + 1) * (maxOrig.second - minOrig.second + 1) % 2 != 0) {
        return false;
    }
    if (canFitRight(minOrig, maxOrig)) {
        return true;
    }
    swap(n, m);
    for (int i = 0; i < n; i++) {
        string s = grid[i];
        reverse(s.begin(), s.end());
        grid[i] = s;
    }
    if (canFitRight(minOrig, maxOrig)) {
        return true;
    }
    return false;
}

void writeOutput(bool res) {
    cout << (res ? "YES" : "NO") << endl;
}

int main() {
