#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n), size(n, 1) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return;
        if (size[x] < size[y]) swap(x, y);
        parent[y] = x;
        size[x] += size[y];
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> p(n);
    for (auto& x : p) cin >> x, x--;
    vector<int> b(n);
    for (auto& x : b) cin >> x;

    int cnt = 0;
    for (int i = 0; i < n; i++) if (b[i]) cnt++;

    DSU dsu(n);
    for (int i = 0; i < n; i++) dsu.unite(i, p[i]);

    vector<int> cycle_size(n);
    for (int i = 0; i < n; i++) {
        int root = dsu.find(i);
        cycle_size[root]++;
    }

    int res = 2;
    for (int i = 0; i < n; i++) if (cycle_size[i] > 0) {
        if (cycle_size[i] % 2 == 0) res = 0;
        else res = 1;
    }

    if (cnt == 0) res++;
    else if (cnt % 2 == 0) res++;

    cout << res << '\n';

    return 0;
}

