pair<int, pair<int, int>> compute(int K, int M) {
    int min_row = K / 2 + 1;
    int min_cost = numeric_limits<int>::max();
    pair<int, pair<int, int>> result;

    for (int row = 1; row <= K; ++row) {
        int start = max(1, (K - M) / 2 + 1 - abs(row - min_row));
        int end = min(K - M + 1, (K + M) / 2 + 1 - abs(row - min_row));

        if (start <= end) {
            int cost = abs(row - min_row) * K + (start + end - M - 1) / 2;
            if (cost < min_cost ||
                (cost == min_cost && row < result.first) ||
                (cost == min_cost && row == result.first && start < result.second.first)) {
                min_cost = cost;
                result = {row, {start, start + M - 1}};
            }
        }
    }

    return result;
}

