    vector<int> tree;
    int size;

    SegmentTree(int n) {
        size = n;
        tree.assign(4 * n, INF);
    }

    void update(int idx, int val, int node = 1, int start = 0, int end = size - 1) {
        if (start == end) {
            tree[node] = min(tree[node], val);
            return;
        }
        int mid = (start + end) / 2;
        if (idx <= mid)
            update(idx, val, 2 * node, start, mid);
        else
            update(idx, val, 2 * node + 1, mid + 1, end);
        tree[node] = min(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int l, int r, int node = 1, int start = 0, int end = size - 1) {
        if (r < start || end < l)
            return INF;
        if (l <= start && end <= r)
            return tree[node];
