#include <cmath>

using namespace std;

class Fraction {
public:
    long long numerator, denominator;

    Fraction(long long n, long long d) : numerator(n), denominator(d) {
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        simplify();
    }

    void simplify() {
        long long g = gcd(numerator, denominator);
        numerator /= g;
        denominator /= g;
    }

    long long gcd(long long a, long long b) const {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    Fraction operator+(const Fraction& other) const {
        long long n = numerator * other.denominator + other.numerator * denominator;
        long long d = denominator * other.denominator;
        return Fraction(n, d);
    }

    Fraction operator/(const Fraction& other) const {
        long long n = numerator * other.denominator;
        long long d = denominator * other.numerator;
        return Fraction(n, d);
    }
};

long long sum_of_digits(long long n, long long base) {
    long long sum = 0;
    while (n > 0) {
        sum += n % base;
        n /= base;
    }
    return sum;
