        smatch match = *i;
        string word = text.substr(last_pos, match.position() - last_pos);
        regex word_pattern("\\s+");
        word = regex_replace(word, word_pattern, " ");
        result += word + match.str(0) + " ";
        last_pos = match.position() + match.length();
    }

    string last_word = text.substr(last_pos);
    regex last_word_pattern("\\s+");
    last_word = regex_replace(last_word, last_word_pattern, " ");
    result += last_word;

    cout << result << endl;

    return 0;
}

