double time_to_reach_with_acceleration(double distance, double acceleration, double max_speed) {
    double time_to_max_speed = max_speed / acceleration;
    double distance_to_max_speed = 0.5 * acceleration * time_to_max_speed * time_to_max_speed;
    if (distance_to_max_speed >= distance) {
        // Only acceleration phase
        double t = sqrt((2 * distance) / acceleration);
        return t;
    } else {
        // Acceleration and then constant speed
        double remaining_distance = distance - distance_to_max_speed;
        double t_accel = time_to_max_speed;
        double t_const = remaining_distance / max_speed;
        return t_accel + t_const;
    }
}

double time_to_reach_with_constant_speed(double distance, double speed) {
    return distance / speed;
}

double calculate_arrival_time(int i, int n, double a, double d, vector<pair<int, int>>& trolleybuses, vector<double>& arrival_times) {
    int ti = trolleybuses[i].first;
    int vi = trolleybuses[i].second;

    double max_possible_speed = min((double)vi, sqrt((2 * a * d)));
    double time_if_alone = time_to_reach_with_acceleration(d, a, max_possible_speed);

    if (i == 0) {
        arrival_times[i] = ti + time_if_alone;
        return arrival_times[i];
    } else {
        double catch_up_time = calculate_arrival_time(i - 1, n, a, d, trolleybuses, arrival_times);
        double time_to_catch_up = time_to_reach_with_constant_speed(d, max_possible_speed);
        double distance_if_alone_at_catch_up_time = (catch_up_time - ti) * max_possible_speed;

        if (distance_if_alone_at_catch_up_time >= d) {
            // This trolleybus would arrive earlier than the previous one if alone, but it can't overtake
            arrival_times[i] = catch_up_time;
        } else {
            // This trolleybus arrives after the previous one
            arrival_times[i] = ti + time_if_alone;
        }

        // Check if this trolleybus can catch up with the previous one
        double time_to_reach_previous_trolleybus_position = time_to_reach_with_acceleration(d, a, max_possible_speed);
        if (ti + time_to_reach_previous_trolleybus_position <= catch_up_time) {
            // This trolleybus catches up with the previous one
            arrival_times[i] = catch_up_time;
        }

        return arrival_times[i];
    }
}

