struct Trolleybus {
    double time;
    double speed;
};

double calculateTime(double acceleration, double distance, double maxSpeed) {
    double timeToMaxSpeed = maxSpeed / acceleration;
    double distanceToMaxSpeed = 0.5 * acceleration * timeToMaxSpeed * timeToMaxSpeed;
    if (distance <= distanceToMaxSpeed) {
        return sqrt(2 * distance / acceleration);
    } else {
        return timeToMaxSpeed + (distance - distanceToMaxSpeed) / maxSpeed;
    }
}

