    long long factor = 1;
    long long nextThreshold = p[0];
    long long figuresDestroyed = 0;
    long long index = 0;

    for (; index < n; ++index) {
        Figure& fig = figures[index];
        while (fig.count > 0) {
            if (figuresDestroyed + 1 > nextThreshold) {
                factor++;
                if (index < t) {
                    nextThreshold = p[index];
                } else {
                    nextThreshold =numeric_limits<long long>::max();
                }
                --fig.count;
                total += fig.cost * factor;
                figuresDestroyed++;
