    for (const auto& [k, _] : figures) {
        counts.push_back(k);
    }

    long long total_points = 0;
    int factor = 1;
    int next_pi_idx = 0;
    int next_pi = (next_pi_idx < t) ? p[next_pi_idx] : numeric_limits<int>::max();

