long long next_smaller(long long n) {
    for (long long i = n - 1; i >= 2; --i) {
        if (n % i == 0) {
            return i;
        }
    }
    return -1;
}
long long compute(long long n, unordered_map<long long, long long>& memo) {
    if (n == 1) {
        return 1;
    }
    if (memo.find(n) != memo.end()) {
        return memo[n];
    }
    long long res = n + compute(next_smaller(n), memo);
    long long mn = next_smaller(n);
    while (mn > 1) {
        res = max(res, n + compute(mn, memo));
        mn = next_smaller(mn);
    }
    memo[n] = res;
    return res;
}
