    sort(primes.begin(), primes.end());
    ll ans = num;
    for (int i = 0; i < primes.size() - 1; i++) {
        ans += primes[i];
        num /= primes[i];
        if (num == 1) break;
    }
    primes.clear();
    return ans;
}

