// Function to generate Fibonacci sequence up to n
std::vector<int> generateFibonacci(int n) {
    std::vector<int> fibSequence = {0, 1};
    while (fibSequence.back() < n) {
        fibSequence.push_back(fibSequence[fibSequence.size() - 1] + fibSequence[fibSequence.size() - 2]);
    }
    return fibSequence;
}

// Function to find three Fibonacci numbers that sum up to n
std::vector<int> findFibonacciTriple(int n, const std::vector<int>& fibSequence) {
    for (int a : fibSequence) {
        for (int b : fibSequence) {
            for (int c : fibSequence) {
                if (a + b + c == n) {
                    return {a, b, c};
                }
            }
        }
    }
    return {}; // Return empty vector if no combination found
}

