int calculateInversions(const vector<string>& original, const vector<string>& perm) {
    int inversions = 0;
    for (int i = 0; i < perm.size(); ++i) {
        int idxOrig = -1;
        for (int j = 0; j < original.size(); ++j) {
            if (original[j] == perm[i]) {
                idxOrig = j;
                break;
            }
        }
        for (int j = 0; j < i; ++j) {
            int idxOrigOther = -1;
            for (int k = 0; k < original.size(); ++k) {
                if (original[k] == perm[j]) {
                    idxOrigOther = k;
                    break;
                }
            }
            if (idxOrig < idxOrigOther) {
                inversions++;
            }
        }
    }
    return inversions;
}

