using namespace std;

void printGraph(int n, const vector<vector<int>>& graph) {
    cout << n << endl;
    for (const auto& row : graph) {
        for (int c : row) {
            cout << c;
        }
        cout << endl;
    }
}

int main() {
    int k;
    cin >> k;

    if (k == 1) {
        printGraph(3, {
            {0, 1, 1},
            {1, 0, 1},
            {1, 1, 0}
        });
        return 0;
    }

    int n = 5;
    vector<vector<int>> graph(n, vector<int>(n, 0));

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            graph[i][j] = 1;
            graph[j][i] = 1;
        }
    }

    int currK = 9;
    while (currK < k) {
        ++n;
        graph.resize(n, vector<int>(n, 0));
        for (int i = 0; i < n - 1; ++i) {
            graph[i][n - 1] = 1;
            graph[n - 1][i] = 1;
        }
        currK += (n - 1) * (n - 2) / 2;
    }

    int diff = currK - k;
    for (int i = n - 1; i >= 2; --i) {
        int toSubtract = (i - 1) * (i - 2) / 2;
        if (diff <= toSubtract) {
            for (int j = i - 1; j >= 2; --j) {
                if (diff == 0) break;
                graph[j][n - 1] = 0;
                graph[n - 1][j] = 0;
                --diff;
            }
            break;
        } else {
            diff -= toSubtract;
            for (int j = 0; j < i; ++j) {
                graph[j][n - 1] = 0;
                graph[n - 1][j] = 0;
            }
        }
    }

    printGraph(n, graph);

    return 0;
}

