    int cycles = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                if (graph[i][j] == '1' && graph[j][k] == '1' && graph[k][i] == '1') {
                    cycles++;
                }
            }
        }
    }
    return cycles;
}

