    vector<vector<char>> graph(n, vector<char>(n, '0'));
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            graph[i][j] = '1';
            graph[j][i] = '1';
        }
    }
    return graph;
}

