int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> p[i];
    }

    long double res = 0.0;

    dp[1][0] = 1 - p[1]; // probability of X
    dp[1][1] = p[1];     // probability of O
    dp[1][2] = 0.0;

    for (int i = 2; i <= n; ++i) {
        dp[i][0] = (1 - p[i]) * (dp[i-1][0] + dp[i-1][1] + dp[i-1][2]); // X
        dp[i][1] = p[i] * (1 - p[i]) * (dp[i-1][0] + dp[i-1][1] + dp[i-1][2]); // OX
        dp[i][2] = p[i] * (dp[i-1][1] + dp[i-1][2]); // OO
    }

    long double cur_p = 0.0;
    long double cur_len = 0.0;

    for (int i = 1; i <= n; ++i) {
        if (abs(p[i] - 0.0) < EPS) {
            cur_p = 0.0;
            cur_len = 0.0;
        } else if (abs(p[i] - 1.0) < EPS) {
            cur_len += 1.0;
            res += (cur_len + 1) * cur_len * (cur_p + p[i]);
            cur_p += p[i];
        } else {
            long double add = p[i] * (cur_p + p[i]);
            res += add * (2 * cur_len + 1);
            cur_p = p[i] * cur_p;
            cur_len = cur_len * p[i];
        }
    }

    for (int i = 1; i <= n; ++i) {
        long double prob = dp[i][2];
        res += prob * (i * i);
    }

