std::string restore_address(const std::string& s) {
    // Find the protocol
    std::string protocol;
    if (s.find("http") == 0) {
        protocol = "http";
    } else if (s.find("ftp") == 0) {
        protocol = "ftp";
    } else {
        throw std::invalid_argument("Invalid protocol");
    }

    // Remove the protocol from the string
    std::string remaining = s.substr(protocol.length());

    // Find the domain and context
    size_t ru_pos = remaining.find("ru");
    if (ru_pos == std::string::npos) {
        throw std::invalid_argument("Invalid domain");
    }

    std::string domain = remaining.substr(0, ru_pos);
    std::string context = remaining.substr(ru_pos + 2); // Skip "ru"

    // Construct the address
    std::string address = protocol + "://" + domain + ".ru";
    if (!context.empty()) {
        address += "/" + context;
    }

    return address;
}

