#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

class Permutation {
public:
    vector<int> p;

    Permutation(int n) : p(n + 1, 0) {}
    Permutation(vector<int> p) : p(p) {}

    Permutation compose(const Permutation& other) const {
        Permutation result(other.p.size());
        for (int i = 1; i < result.p.size(); ++i) {
            result.p[i] = p[other.p[i]];
        }
        return result;
    }

    Permutation inverse() const {
        Permutation result(p.size());
        for (int i = 1; i < result.p.size(); ++i) {
            result.p[p[i]] = i;
        }
        return result;
    }

    bool operator==(const Permutation& other) const {
        return p == other.p;
    }
};

Permutation initialPermutation(int n) {
    Permutation p(n);
    for (int i = 1; i <= n; ++i) {
        p.p[i] = i;
    }
    return p;
}

void readPermutation(int n, Permutation& p) {
    p = Permutation(n);
    for (int i = 1; i <= n; ++i) {
        int x;
        cin >> x;
        p.p[i] = x;
    }
}

bool isPossible(int k, const Permutation& q, const Permutation& s) {
    vector<Permutation> current(1, initialPermutation(q.p.size() - 1));
    for (int step = 0; step < k; ++step) {
        vector<Permutation> next;
        for (const auto& p : current) {
            Permutation p_q = p.compose(q);
            if (find(next.begin(), next.end(), p_q) == next.end()) {
                next.push_back(p_q);
            }
            Permutation p_q_inv = p.compose(q.inverse());
            if (find(next.begin(), next.end(), p_q_inv) == next.end()) {
                next.push_back(p_q_inv);
            }
        }
        current = next;
    }
    return find(current.begin(), current.end(), s) != current.end();
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    Permutation q(n);
    readPermutation(n, q);

    Permutation s(n);
    readPermutation(n, s);

    if (initialPermutation(n) == s) {
        cout << "NO" << endl;
        return 0;
    }

    if (isPossible(k, q, s)) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

