using namespace std;

// Function to apply permutation q to permutation p
vector<int> apply_permutation(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); ++i) {
        result[i] = p[q[i] - 1];
    }
    return result;
}

// Function to compute the inverse permutation of q
vector<int> inverse_permutation(const vector<int>& q) {
    vector<int> result(q.size());
    for (int i = 0; i < q.size(); ++i) {
        result[q[i] - 1] = i + 1;
    }
    return result;
}

// Function to apply the inverse permutation to p
vector<int> apply_inverse_permutation(const vector<int>& p, const vector<int>& q_inv) {
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); ++i) {
        result[i] = p[q_inv[i] - 1];
    }
    return result;
}

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> q(n);
    for (int i = 0; i < n; ++i) {
        cin >> q[i];
    }

    vector<int> s(n);
    for (int i = 0; i < n; ++i) {
        cin >> s[i];
