    vector<int> initial_perm(n);
    for (int i = 0; i < n; ++i) {
        initial_perm[i] = i + 1;
    }
    if (initial_perm == s) {
        cout << "NO" << endl;
        return 0;
    }

    // Generate all possible permutations after k moves
    set<vector<int>> visited;
    visited.insert(initial_perm);

    vector<vector<int>> current_permutations;
    current_permutations.push_back(initial_perm);

    for (int i = 0; i < k; ++i) {
