    for (int i = 0; i < a.size(); ++i) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

bool dfs(vector<int> current, const vector<int>& q, const vector<int>& inv_q, const vector<int>& target, int k) {
    if (k == 0) {
        return is_equal(current, target);
    }
    vector<int> next1 = apply_permutation(current, q);
    vector<int> next2 = apply_permutation(current, inv_q);
    if (!is_equal(next1, target) && !is_equal(next2, target)) {
        return dfs(next1, q, inv_q, target, k - 1) || dfs(next2, q, inv_q, target, k - 1);
    } else if (!is_equal(next1, target)) {
        return dfs(next1, q, inv_q, target, k - 1);
    } else if (!is_equal(next2, target)) {
        return dfs(next2, q, inv_q, target, k - 1);
    } else {
        return false;
    }
}

