#include <cmath>
#include <algorithm>

using namespace std;

struct Point {
    double x, y;
    double angle;
};

double angleBetweenPoints(const Point& p1, const Point& p2) {
    double dotProduct = p1.x * p2.x + p1.y * p2.y;
    double magnitude1 = sqrt(p1.x * p1.x + p1.y * p1.y);
    double magnitude2 = sqrt(p2.x * p2.x + p2.y * p2.y);
    double cosTheta = dotProduct / (magnitude1 * magnitude2);
    return acos(cosTheta) * (180 / M_PI);
}

int main() {
    int n;
    cin >> n;

    vector<Point> points(n);
    for (int i = 0; i < n; ++i) {
        cin >> points[i].x >> points[i].y;
        if (points[i].y == 0) {
            points[i].angle = (points[i].x > 0) ? 0 : 180;
        } else if (points[i].x == 0) {
            points[i].angle = (points[i].y > 0) ? 90 : 270;
        } else {
            points[i].angle = atan2(points[i].y, points[i].x) * (180 / M_PI);
            if (points[i].angle < 0) {
                points[i].angle += 360;
            }
        }
    }

    sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
        return a.angle < b.angle;
    });

