struct Box {
    long long k;
    long long a;
};

bool compare(Box a, Box b) {
    return a.k < b.k;
}

long long countBoxes(Box boxes[], int n, long long currentK, long long &currentCount) {
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        if (boxes[i].k == currentK) {
            total += boxes[i].a;
        }
    }
    if (total > currentCount) {
        long long remainder = total - currentCount;
        long long newBoxes = (remainder + 3) / 4; // ceiling division
        currentCount = 1;
        return newBoxes + countBoxes(boxes, n, currentK, currentCount);
    } else {
        currentCount -= total;
        return 0;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

