int used_rods[MAX_M]; // 0 - unused, 1 - used as straight, 2 - used as bent
int result[MAX_N]; // -1 or rod index (1-based)

// Checks if a rod of given length can be used for a straight connection between two nails
bool can_use_straight(int rod_length, const Nail& nail1, const Nail& nail2) {
    int dx = abs(nail1.x - nail2.x);
    int dy = abs(nail1.y - nail2.y);
    return (dx == 0 && rod_length == dy) || (dy == 0 && rod_length == dx);
}

// Checks if a rod of given length can be used for a bent connection between three nails
bool can_use_bent(int rod_length, const Nail& nail1, const Nail& nail2, const Nail& nail3) {
    int dx1 = abs(nail1.x - nail2.x);
    int dy1 = abs(nail1.y - nail2.y);
    int dx2 = abs(nail2.x - nail3.x);
    int dy2 = abs(nail2.y - nail3.y);

    // Check for L-shape and correct lengths
    return (dx1 != 0 && dy1 == 0 && dy2 != 0 && dx2 == 0 && dx1 + dy2 == rod_length) ||
           (dy1 != 0 && dx1 == 0 && dx2 != 0 && dy2 == 0 && dy1 + dx2 == rod_length);
}

bool try_assign_rod(int current_nail, int last_nail, int prev_nail, vector<int>& available_rods, int& current_rod_index) {
    if (current_nail >= n) return true; // Successfully assigned all nails

    // Check for straight rod assignment
    for (int i = 0; i < available_rods.size(); ++i) {
        int rod_index = available_rods[i];
        if (can_use_straight(rod_lengths[rod_index], nails[last_nail], nails[current_nail])) {
            // Assign rod and mark as used
            result[current_nail] = -1; // Not a bend point
            used_rods[rod_index] = 1; // Mark as used straight
            available_rods.erase(available_rods.begin() + i);

            // Recursively try next nail
            if (try_assign_rod(current_nail + 1, current_nail, last_nail, available_rods, current_rod_index)) {
                return true;
            }

            // Backtrack if assignment didn't lead to a solution
            available_rods.push_back(rod_index);
            used_rods[rod_index] = 0; // Unmark
            result[current_nail] = 0; // Reset
        }
    }

    // If no straight rod works, try bent rod assignment
    for (int i = 0; i < available_rods.size(); ++i) {
        int rod_index = available_rods[i];
        if (can_use_bent(rod_lengths[rod_index], nails[prev_nail], nails[last_nail], nails[current_nail])) {
            // Assign rod and mark as used
