    if (horizontal && vertical) {
        return distance(a, b) + distance(b, c);
    } else if (horizontal && !vertical) {
        return distance(a, b) + distance(b, c) / 2;
    } else if (!horizontal && vertical) {
        return distance(a, b) / 2 + distance(b, c);
    } else {
        return (distance(a, b) + distance(b, c)) / 2;
    }
}

