#include <algorithm>

using namespace std;

const int MAX_N = 505;
const int MAX_M = 505;

struct Nail {
    int x, y;
};

int n, m;
Nail nails[MAX_N];
int rods[MAX_M];
bool used_rods[MAX_M];
int result[MAX_N];

int calculate_length(const Nail& a, const Nail& b, const Nail& c) {
    int dx1 = b.x - a.x;
    int dy1 = b.y - a.y;
    int dx2 = c.x - b.x;
    int dy2 = c.y - b.y;
    return abs(dx1) + abs(dy1) + abs(dx2) + abs(dy2);
}

bool solve() {
    fill(used_rods, used_rods + m, false);
    fill(result, result + n, -1);

    vector<int> available_rods;
    for (int i = 0; i < m; ++i) {
        available_rods.push_back(i);
    }

    for (int i = 0; i < n; i += 2) {
        if (i + 1 >= n) break;

        int length = calculate_length(nails[i], nails[i + 1], nails[i + 2]);
        if (length > m * 200000) {
            return false; // Not enough rods
        }

        auto it = find_if(available_rods.begin(), available_rods.end(),
            [&length](int rod_index) { return rods[rod_index] == length; });
        if (it == available_rods.end()) {
            return false; // Rod not found
        }
        int rod_index = *it;
        available_rods.erase(it);
        used_rods[rod_index] = true;
        result[i + 1] = rod_index + 1;
    }

    return true;
}

