#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

// Union-Find Data Structure
class UnionFind {
public:
    vector<int> parent, rank;

    UnionFind(int n) : parent(n + 1), rank(n + 1) {
        for (int i = 1; i <= n; ++i) {
            parent[i] = i; // Initially, each element is its own parent
            rank[i] = 0;    // Initially, each element's rank is 0
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    void unionSet(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) { // If x and y are not in the same set
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
};

bool checkReachability(int n, const vector<int>& permutation, const vector<int>& favouriteNumbers) {
    UnionFind uf(n);

    // Union cells that can reach each other based on favourite numbers
    for (int i = 1; i <= n; ++i) {
        int j = i + favouriteNumbers[i - 1];
        if (1 <= j && j <= n) {
            uf.unionSet(i, j);
        }
        j = i - favouriteNumbers[i - 1];
        if (1 <= j && j <= n) {
            uf.unionSet(i, j);
        }
    }

    // Check if each cell's value is in the same set as its position
    for (int i = 1; i <= n; ++i) {
        if (uf.find(i) != uf.find(permutation[i - 1])) {
            return false; // Permutation value not reachable from its position
        }
    }

    return true; // All permutation values are reachable from their positions
}

int main() {
    int n;
    cin >> n;

    vector<int> permutation(n);
    for (int i = 0; i < n; ++i) {
        cin >> permutation[i];
    }

    vector<int> favouriteNumbers(n);
    for (int i = 0; i < n; ++i) {
        cin >> favouriteNumbers[i];
    }

    if (checkReachability(n, permutation, favouriteNumbers)) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

