    long long sa = 0, sg = 0;
    res.clear();
    for (int i = 0; i < n; ++i) {
        if (a[i] < g[i]) {
            res += 'A';
            sa += a[i];
        } else {
            res += 'G';
            sg += g[i];
        }
    }
    if (abs(sa - sg) <= 500) return true;

    vector<pair<int, int>> eggs;
    for (int i = 0; i < n; ++i) {
        eggs.emplace_back(a[i] - g[i], i);
    }
    sort(eggs.begin(), eggs.end());

    sa = 0, sg = 0;
    res.clear();
    for (const auto& [diff, idx] : eggs) {
        if (diff < 0) {
            res += 'G';
            sg += g[idx];
        } else {
            res += 'A';
            sa += a[idx];
        }
    }
    if (abs(sa - sg) <= 500) return true;

    // Try to swap one egg
    for (const auto& [diff, idx] : eggs) {
        if (diff != 0) {
            char ch = (res[idx] == 'A') ? 'G' : 'A';
            res[idx] = ch;
            long long new_sa = sa, new_sg = sg;
            if (ch == 'A') new_sa += a[idx] - g[idx];
            else new_sg += g[idx] - a[idx];
            if (abs(new_sa - new_sg) <= 500) return true;
            res[idx] = (ch == 'A') ? 'G' : 'A'; // Restore
        }
    }

    return false;
}

