using namespace std;

bool isPrime(int p) {
    if (p < 2) return false;
    for (int i = 2; i * i <= p; ++i) {
        if (p % i == 0) return false;
    }
    return true;
}

int numPrimitiveRoots(int p) {
    if (!isPrime(p)) throw invalid_argument("Input must be a prime number");
    if (p == 2) return 1;

    int phi = p - 1;
    vector<int> primeFactors;
    int n = phi;
    for (int i = 2; i * i <= n; ++i) {
        while (n % i == 0) {
            primeFactors.push_back(i);
            n /= i;
        }
    }
    if (n > 1) primeFactors.push_back(n);

    unordered_set<int> uniqueFactors(primeFactors.begin(), primeFactors.end());

    int count = 0;
    for (int g = 2; g < p; ++g) {
        bool isPrimitiveRoot = true;
        for (int q : uniqueFactors) {
            if (pow(g, phi / q, p) == 1) {
                isPrimitiveRoot = false;
                break;
            }
        }
        if (isPrimitiveRoot) ++count;
    }
    return count;
}

int main() {
    int p;
    cin >> p;
    cout << numPrimitiveRoots(p) << endl;
    return 0;
}

