int main() {
    int p;
    cin >> p;

    vector<bool> primitive_roots(p, true);

    for (int x = 2; x < p; ++x) {
        int ord = 1;
        for (int i = 1; i < p - 1; ++i) {
            int nx = (long long)x * x % p;
            if (nx == 1) {
                primitive_roots[x - 1] = false;
                break;
            }
            x = nx;
            ord++;
        }
    }

    int count = 0;
    for (bool is_primitive : primitive_roots) {
        if (is_primitive) {
            count++;
        }
    }

    cout << count - 1 << endl; // subtract 1 because 1 is not a primitive root

    return 0;
}

