    if (k == 2 && n > 2) {
        string res;
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) res += 'a';
            else res += 'b';
        }
        return res;
    }
    if (k == 2 && n == 2) return "ab";
    if (k == 2 && n == 1) return "a";
    string res;
    for (int i = 0; i < n; i++) {
        if (i % 2 == 0) res += 'a';
        else res += 'b';
    }
    if (n % 2 == 1) res[n-1] = 'c';
    if (k > 3) {
        int idx = n-2;
