bool can_rearrange(const vector<int>& arr) {
    int count = 0;
    int prev = -1;
    for (int num : arr) {
        if (num == prev) {
            ++count;
        } else {
            prev = num;
            count = 1;
        }
        if (count > (arr.size() + 1) / 2) {
            return false;
        }
    }
    return true;
}

