// Function to get all possible moves from a given position
map<string, pair<char, int>> getPossibleMoves(pair<char, int> pos) {
    map<string, pair<char, int>> moves;
    char c = pos.first;
    int r = pos.second;

    // Check all 8 possible directions
    if (c > 'a' && r < 8) moves["LU"] = {c - 1, r + 1};
    if (c < 'h' && r < 8) moves["RU"] = {c + 1, r + 1};
    if (c > 'a' && r > 1) moves["LD"] = {c - 1, r - 1};
    if (c < 'h' && r > 1) moves["RD"] = {c + 1, r - 1};
    if (c > 'a') moves["L"] = {c - 1, r};
    if (c < 'h') moves["R"] = {c + 1, r};
    if (r < 8) moves["U"] = {c, r + 1};
    if (r > 1) moves["D"] = {c, r - 1};

    return moves;
}

int main() {
    string start, end;
    getline(cin, start);
    getline(cin, end);

    // Convert input to pair format
    pair<char, int> startPos = {start[0], start[1] - '0'};
    pair<char, int> endPos = {end[0], end[1] - '0'};

    // BFS queue
    queue<Move> q;
    q.push({ "", startPos });

    // Visited set
    map<pair<char, int>, bool> visited;
    visited[startPos] = true;

    // Result path
    string resultPath;

    // BFS
    while (!q.empty()) {
        Move current = q.front();
        q.pop();

        // If this is the destination position, store the path
        if (current.pos == endPos) {
            resultPath = current.path;
            break;
        }

        // Get all possible moves from the current position
        map<string, pair<char, int>> moves = getPossibleMoves(current.pos);

        // Explore each possible move
        for (auto& move : moves) {
            if (!visited[move.second]) {
                visited[move.second] = true;
                q.push({ current.path + move.first, move.second });
            }
        }
    }

    // Output the result
    cout << resultPath.length() << endl;
    cout << resultPath << endl;

    return 0;
}

