            atCount++;
        }
    }
    return atCount == 1 && email.find('@') != 0 && email.find('@') != email.length() - 1;
}

bool splitEmails(const std::string& input, std::string& output) {
    if (input.empty()) {
        return true; // Empty input is a valid case (no emails)
    }

    for (int i = 1; i < input.length() - 1; ++i) {
        if (input[i] == '@') {
            std::string firstPart = input.substr(0, i);
            std::string rest = input.substr(i + 1);
            if (!firstPart.empty() && isValidEmail(firstPart + "@" + rest)) {
                output += firstPart + "@";
                if (splitEmails(rest, output)) {
                    return true;
                }
                output.erase(output.find_last_not_of(',') + 1);
            } else {
                std::string secondEmail;
                if (splitEmails(rest, secondEmail)) {
                    output += firstPart + "," + secondEmail;
                    return true;
                }
            }
        }
    }

    // If no split found, try as a single email
    if (isValidEmail(input)) {
        output += input;
        return true;
    }

    return false;
}

