    q.push({{a, b, c, d}, ""});

    unordered_set<string> visited;

    while (!q.empty()) {
        Node node = q.front();
        q.pop();

        auto& state = node.state;
        int& x = state[0];
        int& y = state[1];
        int& z = state[2];
        int& w = state[3];

        string key = to_string(x) + " " + to_string(y) + " " + to_string(z) + " " + to_string(w);
        if (visited.find(key) != visited.end()) continue;
        visited.insert(key);

        if (x == 1 && y == 1 && z == 1 && w == 1) {
            cout << node.path << endl;
            return;
        }

        // Check for division operations
        if (x % 2 == 0 && y % 2 == 0) {
            q.push({{x / 2, y / 2, z, w}, node.path + "/1"}});
        }
        if (y % 2 == 0 && z % 2 == 0) {
            q.push({{x, y / 2, z / 2, w}, node.path + "/2"}});
        }
        if (z % 2 == 0 && w % 2 == 0) {
            q.push({{x, y, z / 2, w / 2}, node.path + "/3"}});
        }
        if (w % 2 == 0 && x % 2 == 0) {
