using namespace std;

pair<int, int> go(int x, int y, int n, int m, vector<pair<int, int>>& path) {
    path.push_back({x, y});
    if (x == n && y == m) return {0, 0};
    int dx[] = {0, 1, 0, -1}, dy[] = {1, 0, -1, 0};
    for (int k = 0; k < 4; ++k) {
        int nx = x + dx[k], ny = y + dy[k];
        if (1 <= nx && nx <= n && 1 <= ny && ny <= m && !count(path.begin(), path.end(), pair<int, int>{nx, ny})) {
            auto res = go(nx, ny, n, m, path);
            if (res.first != -1) return {nx, ny, res.first, res.second, res.third, res.fourth};
        }
    }
    return {-1, -1, -1, -1, -1, -1};
}

void solve() {
    int n, m;
    cin >> n >> m;

    if (n == 1 && m == 1) {
        cout << "0\n1 1\n1 1" << endl;
        return;
