    vector<string> teleporters;
    vector<string> path;

    if ((n * m) % 2 == 0) {
        // No teleporters needed for even-sized grids (except 2x2)
        if (n == 2 && m == 2) {
            teleporters.push_back("1 1 2 2");
            teleporters.push_back("2 2 1 1");
            path.push_back("1 1");
            path.push_back("1 2");
            path.push_back("2 2");
            path.push_back("2 1");
            path.push_back("1 1");
        } else {
            bool dir = true; // true for right/down, false for left/up
            int x = 1, y = 1;
            path.push_back("1 1");
            while (x < n || y < m) {
                if (dir) {
                    if (y < m) {
                        y++;
                    } else {
                        x++;
                    }
                } else {
                    if (y > 1) {
                        y--;
                    } else {
                        x++;
                    }
                }
                path.push_back(to_string(x) + " " + to_string(y));
                if (x == n && y == m) dir = false;
                if (x == 1 && y == 1) dir = true;
            }
            path.push_back("1 1");
        }
    } else {
        // One teleporter needed for odd-sized grids
        teleporters.push_back(to_string(n) + " " + to_string(m) + " 1 1");
        bool dir = true; // true for right/down, false for left/up
