#include <string>
#include <algorithm>

using namespace std;

struct Word {
    string s;
    bool operator<(const Word& other) const {
        return s < other.s;
    }
};

bool placeWord(vector<vector<char>>& grid, const string& word, int x, int y, int dx, int dy) {
    int n = grid.size();
    int m = grid[0].size();
    for (int i = 0; i < word.size(); ++i) {
        int nx = x + i * dx;
        int ny = y + i * dy;
        if (nx < 0 || nx >= n || ny < 0 || ny >= m) return false;
        if (grid[nx][ny] != '.' && grid[nx][ny] != word[i]) return false;
    }
    for (int i = 0; i < word.size(); ++i) {
        int nx = x + i * dx;
        int ny = y + i * dy;
        grid[nx][ny] = word[i];
    }
    return true;
}

bool isValid(const vector<vector<char>>& grid) {
    int n = grid.size();
    int m = grid[0].size();
    int black = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == '.') {
                black++;
                // Check if the black cell is surrounded by letters
                int surrounded = 0;
                for (int dx = -1; dx <= 1; ++dx) {
                    for (int dy = -1; dy <= 1; ++dy) {
                        if (dx == 0 && dy == 0) continue;
                        int nx = i + dx;
                        int ny = j + dy;
                        if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] != '.') {
                            surrounded++;
                        }
                    }
                }
                if (surrounded < 2) return false;
            }
        }
    }
    return black == 4;
}

bool solve(vector<string>& words, vector<vector<char>>& grid) {
    if (words.empty()) return isValid(grid);
    string word = words[0];
    words.erase(words.begin());
    int n = grid.size();
    int m = grid[0].size();
    for (int i = 0; i < n; ++i) {
