            if (grid[i][j] == '.') {
                for (int dx = -1; dx <= 1; ++dx) {
                    for (int dy = -1; dy <= 1; ++dy) {
                        if (dx == 0 && dy == 0) continue;
                        if (placeWord(grid, word, i, j, dx, dy)) {
                            if (solve(words, grid)) return true;
                            placeWord(grid, string(word.size(), '.'), i, j, dx, dy);
                        }
                    }
                }
