    for (int k = 0; k < w.len; ++k) {
        int ni = i + k * di, nj = j + k * dj;
        grid[ni][nj] = '.';
    }
}

bool backtrack(vector<Word>& remaining, int pos) {
    if (pos == remaining.size()) return true;

    for (int i = 0; i < grid.size(); ++i) {
