#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

int n;
vector<string> dates;

bool valid(string s) {
    return s[0] != '0' && stoi(s) >= 1000 && stoi(s) <= 2011;
}

string fixDigit(string s, int pos, char c) {
    string res = s;
    res[pos] = c;
    return res;
}

string closestPossible(string s, int prev) {
    string res = s;
    for (int i = 0; i < 4; ++i) {
        for (char c = '0'; c <= '9'; ++c) {
            string newS = fixDigit(s, i, c);
            if (valid(newS) && stoi(newS) >= prev && (res.empty() || stoi(newS) < stoi(res))) {
                res = newS;
            }
        }
    }
    return res;
}

void solve() {
    vector<string> res;
    int prev = 1000;
    for (const auto& date : dates) {
        string newDate = closestPossible(date, prev);
        if (newDate.empty()) {
            cout << "No solution" << endl;
            return;
        }
        res.push_back(newDate);
        prev = stoi(newDate);
    }
    for (const auto& d : res) {
        cout << d << endl;
    }
}

int main() {
    cin >> n;
    dates.resize(n);
    for (auto& date : dates) {
        cin >> date;
    }
    solve();
    return 0;
}

