using namespace std;

vector<int> parse_date(int date) {
    vector<int> digits(4);
    digits[0] = date / 1000;
    digits[1] = (date % 1000) / 100;
    digits[2] = (date % 100) / 10;
    digits[3] = date % 10;
    return digits;
}

int make_date(vector<int> digits) {
    return digits[0] * 1000 + digits[1] * 100 + digits[2] * 10 + digits[3];
}

vector<int> gen_candidates(int date) {
    vector<int> digits = parse_date(date);
    vector<int> candidates;
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j <= 9; ++j) {
            vector<int> new_digits = digits;
            new_digits[i] = j;
            if (new_digits[0] != 0 && make_date(new_digits) >= 1000 && make_date(new_digits) <= 2011) {
                candidates.push_back(make_date(new_digits));
            }
        }
    }
    candidates.push_back(date);
    sort(candidates.begin(), candidates.end());
    candidates.erase(unique(candidates.begin(), candidates.end()), candidates.end());
    return candidates;
}

bool solve(vector<int> &dates, int idx, int last) {
    if (idx == dates.size()) {
        return true;
    }
    vector<int> candidates = gen_candidates(dates[idx]);
    for (int candidate : candidates) {
        if (candidate >= last) {
            dates[idx] = candidate;
            if (solve(dates, idx + 1, candidate)) {
                return true;
            }
        }
    }
    return false;
}

