    double max_equal_energy = total_energy / n;
    double precision = 0.000000001; // Precision for comparison
    double percent_loss = k / 100.0;

    // Check if the calculated max_equal_energy is achievable
    double remaining_energy = 0.0;
    for (double energy : energies) {
        if (energy > max_equal_energy) {
            double excess_energy = energy - max_equal_energy;
            double loss = excess_energy * percent_loss;
            remaining_energy += excess_energy - loss;
        } else {
            double deficit = max_equal_energy - energy;
            remaining_energy -= deficit / (1 - percent_loss);
        }
    }

    // Adjust max_equal_energy based on the remaining energy
    if (remaining_energy > precision) { // More energy than needed
        while (remaining_energy > precision) {
            max_equal_energy += 0.0000001; // Increment slightly
            remaining_energy = 0.0;
            for (double energy : energies) {
                if (energy > max_equal_energy) {
                    double excess_energy = energy - max_equal_energy;
                    double loss = excess_energy * percent_loss;
                    remaining_energy += excess_energy - loss;
                } else {
                    double deficit = max_equal_energy - energy;
                    remaining_energy -= deficit / (1 - percent_loss);
                }
            }
        }
        max_equal_energy -= 0.0000001; // Revert the last increment
    } else if (remaining_energy < -precision) { // Not enough energy
        while (remaining_energy < -precision) {
            max_equal_energy -= 0.0000001; // Decrement slightly
