double find_max_equal-energy(int n, double k, const vector<double>& a) {
    double total_energy = 0.0;
    for (double ai : a) {
        total_energy += ai;
    }

    double low = 0.0;
    double high = (total_energy / n); // Initial high guess
    double epsilon = 1e-9; // Precision threshold
    double max_equal_energy = 0.0;

    while (high - low > epsilon) {
        double mid = (low + high) / 2.0;
        double required_energy = mid * n;

        if (required_energy > total_energy) { // Mid is too high
            high = mid;
        } else { // Mid is feasible or too low
            low = mid;
            max_equal_energy = mid; // Update max if feasible
        }
    }

    // Refine with more precise calculation considering k
    double precision = 1e-10; // Tighten precision for final calculation
    while (high - low > precision) {
        double mid = (low + high) / 2.0;
        double simulated_total = 0.0;

        for (double ai : a) {
            if (ai > mid) { // Simulator transfer from ai to others
                double transferable = ai - mid;
                double loss = (k / 100.0) * transferable;
                simulated_total += transferable - loss; // Account for loss
