#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>

using namespace std;

bool moveController(int &pos, int n, bool &toHead) {
    if (toHead) {
        if (pos == 1) {
            toHead = false;
            return false;
        }
        pos--;
    } else {
        if (pos == n) {
            toHead = true;
            return false;
        }
        pos++;
    }
    return true;
}

bool moveStowaway(int &pos, int n, int controllerPos, string &trainState, int minute) {
    if (trainState[minute] == '0') { // moving
        // stowaway can move to neighbouring or stay
        // to avoid capture, move away from controller if possible
        if (pos < controllerPos && pos + 1 <= n && (pos + 1) != controllerPos) {
            pos++;
        } else if (pos > controllerPos && pos - 1 >= 1 && (pos - 1) != controllerPos) {
            pos--;
        }
        // check capture after move
        if (pos == controllerPos) {
            return false;
        }
    } else { // idle
        // stowaway leaves and enters back, try to move away
        int newPos = (pos + n - controllerPos) % n + 1; // simple evasion strategy
        if (newPos == controllerPos) {
            newPos = (newPos + 1) % n + 1; // adjust if still same
            if (newPos == controllerPos) {
                newPos = (newPos + 1) % n + 1; // one more adjustment
            }
        }
        pos = newPos;
        if (pos == controllerPos) {
            return false;
        }
    }
    return true;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    string direction;
    cin >> direction;
    bool toHead = (direction == "to head");
    string trainState;
    cin >> trainState;

    int controllerPos = k;
    int stowawayPos = m;
    int minute = 0;

    while (trainState[minute] != '1' || minute < (int)trainState.size() - 1) {
        if (trainState[minute] == '0') { // moving
            if (!moveStowaway(stowawayPos, n, controllerPos, trainState, minute)) {
                cout << "Controller " << (minute + 1) << endl;
                return 0;
            }
            if (!moveController(controllerPos, n, toHead)) {
                // direction changed, no action needed
            }
        } else { // idle
            // stowaway leaves
            int oldStowawayPos = stowawayPos;
            // controller moves
            if (!moveController(controllerPos, n, toHead)) {
                // direction changed
            }
            // stowaway enters back
            if (!moveStowaway(stowawayPos, n, controllerPos, trainState, minute)) {
                cout << "Controller " << (minute + 1) << endl;
                return 0;
            }
        }
        minute++;
        if (stowawayPos == controllerPos) {
            cout << "Controller " << (minute + 1) << endl;
            return 0;
        }
    }

    // terminal station, stowaway wins if not caught before
