#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

const int MAX_HEROS = 7;
const int MAX_LIKES = 42;

int likes[MAX_HEROS][MAX_HEROS];
int a, b, c;

struct Team {
    int team[3];
    int diff;
    int totalLikes;
};

bool operator<(const Team &lhs, const Team &rhs) {
    if (lhs.diff == rhs.diff) {
        return lhs.totalLikes > rhs.totalLikes;
    }
    return lhs.diff < rhs.diff;
}

Team bestTeam;

void calculateTeam(vector<int> &distribution, int idx, int teamAssign[MAX_HEROS]) {
    if (idx == MAX_HEROS) {
        int exp[MAX_HEROS];
        int teamSize[3] = {0};
        int totalLikes = 0;

        for (int i = 0; i < MAX_HEROS; i++) {
            teamSize[distribution[i]]++;
            for (int j = 0; j < MAX_HEROS; j++) {
                if (distribution[i] == distribution[j] && likes[i][j] == 1) {
                    totalLikes++;
                }
            }
        }

        exp[0] = a / teamSize[0];
        exp[1] = b / teamSize[1];
        exp[2] = c / teamSize[2];

        int minExp = *min_element(exp, exp + 3);
        int maxExp = *max_element(exp, exp + 3);
        int diff = maxExp - minExp;

        Team currentTeam;
        currentTeam.team[0] = teamSize[0];
        currentTeam.team[1] = teamSize[1];
        currentTeam.team[2] = teamSize[2];
        currentTeam.diff = diff;
        currentTeam.totalLikes = totalLikes;

        if (bestTeam.diff == 0 || currentTeam < bestTeam) {
            bestTeam = currentTeam;
        }

        return;
    }

    for (int i = 0; i < 3; i++) {
        distribution[idx] = i;
        calculateTeam(distribution, idx + 1, teamAssign);
    }
}

int main() {
    int n;
    cin >> n;

    for (int i = 0; i < n; i++) {
        string p, q, likesStr;
        cin >> p >> likesStr >> q;

        int heroP, heroQ;
        string heroes[] = {"Anka", "Chapay", "Cleo", "Dracul", "Hexadecimal", "Snowy", "Troll"};
        for (int j = 0; j < MAX_HEROS; j++) {
            if (p == heroes[j]) heroP = j;
            if (q == heroes[j]) heroQ = j;
        }

        likes[heroP][heroQ] = 1;
    }

    cin >> a >> b >> c;

    bestTeam.diff = INT_MAX;
    vector<int> distribution(MAX_HEROS);
    int teamAssign[MAX_HEROS];
    calculateTeam(distribution, 0, teamAssign);

    cout << bestTeam.diff << " " << bestTeam.totalLikes << endl;

    return 0;
}

