// Structure to represent a bead string with its canonical form
struct BeadString {
    string str;
    string canonical;
};

// Function to generate the canonical form of a bead string
string getCanonical(const string& str) {
    string reverseStr = str;
    reverse(reverseStr.begin(), reverseStr.end());
    string swappedStr;
    for (char c : str) {
        swappedStr += (c == '0' ? '1' : '0');
    }
    string swappedReverseStr;
    for (char c : reverseStr) {
        swappedReverseStr += (c == '0' ? '1' : '0');
    }

    // Choose the smallest among the string, its reverse, swapped, and swapped reverse
    vector<string> candidates = {str, reverseStr, swappedStr, swappedReverseStr};
    return *min_element(candidates.begin(), candidates.end());
}

// Function to generate all possible bead strings of length n
vector<string> generateStrings(int n) {
    vector<string> result;
    string str(n, '0');
    while (true) {
        result.push_back(str);
        // Increment the string (like binary increment)
        int i = n - 1;
        while (i >= 0 && str[i] == '1') {
            str[i] = '0';
            i--;
        }
        if (i < 0) break; // All '1's, stop
        str[i] = '1';
    }
    return result;
}

// Function to group strings by their canonical forms
vector<vector<BeadString>> groupByCanonical(const vector<string>& strings) {
    vector<vector<BeadString>> groups;
    for (const auto& str : strings) {
        string canonical = getCanonical(str);
        bool found = false;
        for (auto& group : groups) {
            if (group[0].canonical == canonical) {
                group.push_back({str, canonical});
                found = true;
                break;
            }
        }
        if (!found) {
            groups.push_back({{str, canonical}});
        }
    }
    return groups;
}

// Function to sort the groups and extract the minimum string from each
vector<string> sortBy MartianRule(const vector<vector<BeadString>>& groups) {
    // Sort the groups by their canonical form (which is the same within a group)
    sort(groups.begin(), groups.end(), [](const auto& a, const auto& b) {
        return a[0].canonical < b[0].canonical;
    });

    vector<string> result;
    for (const auto& group : groups) {
        // Sort the strings within the group by Martian rule and pick the first
        sort(group.begin(), group.end(), [](const auto& a, const auto& b) {
            const string& sa = a.str;
            const string& sb = b.str;
            for (int i = 0; i < sa.size(); ++i) {
                if (sa[i] != sb[i]) {
                    // '0' is considered smaller than '1'
                    return sa[i] < sb[i];
                }
            }
            return false; // Equal
        });
        result.push_back(group[0].str);
    }
    return result;
}

int main() {
    int n, k;
    cin >> n >> k;

    vector<string> allStrings = generateStrings(n);
    vector<vector<BeadString>> groups = groupByCanonical(allStrings);
    vector<string> sortedStrings = sortByMartianRule(groups);

    if (k > (int)sortedStrings.size()) {
        cout << -1 << endl;
    } else {
        cout << sortedStrings[k-1] << endl;
    }

