#include <iostream>
#include <cmath>

long long reflection(long long n) {
    long long res = 0;
    while (n > 0) {
        int digit = n % 10;
        res = res * 10 + (9 - digit);
        n /= 10;
    }
    return res;
}

long long weight(long long n) {
    return n * reflection(n);
}

long long findMaxWeight(long long l, long long r) {
    long long maxWeight = 0;
    for (long long i = l; i <= r; i++) {
        long long currentWeight = weight(i);
        if (currentWeight > maxWeight) {
            maxWeight = currentWeight;
        }
    }
    return maxWeight;
}

