        count++;
        if (selected.find(start) != selected.end()) {
            selected.erase(start);
        } else {
            selected.insert(start);
            if (selected.find(end) != selected.end()) {
                selected.erase(end);
            } else {
                selected.insert(end);
            }
        }
    };

    auto toLeft = [&](int x) {
        return (x - 1) % m == 0;
    };

    auto toRight = [&](int x) {
        return x % m == 0;
    };

    if (a == b) {
        cout << 1 << endl;
        return 0;
    }

    if (toLeft(a) && toRight(b)) {
        cout << 2 << endl;
        return 0;
    }

    if (toLeft(a)) {
        select(a, b);
        if (!toRight(b)) {
            select(b, b);
        }
    } else if (toRight(b)) {
        select(a, b);
        if (!toLeft(a)) {
            select(a, a);
        }
    } else {
        select(a, (a - 1) / m * m + m);
        select((b - 1) / m * m + 1, b);
