using namespace std;

struct Fraction {
    int numerator;
    int denominator;

    Fraction(int n, int d) : numerator(n), denominator(d) {}

    bool operator==(const Fraction& other) const {
        return numerator * other.denominator == other.numerator * denominator;
    }

    bool operator<(const Fraction& other) const {
        return numerator * other.denominator < other.numerator * denominator;
    }
};

Fraction greatestCommonDivisor(int a, int b) {
    int gcd = 1;
    for (int i = 2; i <= min(a, b); ++i) {
        if (a % i == 0 && b % i == 0) {
            gcd = i;
        }
    }
    return Fraction(gcd, 1);
}

Fraction simplify(Fraction f) {
    Fraction gcd = greatestCommonDivisor(f.numerator, f.denominator);
    return Fraction(f.numerator / gcd.numerator, f.denominator / gcd.numerator);
}

Fraction calculateExpectedTosses(int n) {
    static vector<Fraction> memo(10001, Fraction(0, 1)); // Initialize memo with zeros
    if (memo[n].numerator != 0) return memo[n]; // Return cached result if available

    if (n == 1) return Fraction(0, 1); // Base case: 0 tosses for 1 knight
    if (n == 2) return Fraction(1, 1); // Base case: 1 toss for 2 knights

    Fraction bestEffort(1000000, 1); // Initialize with a large value
    for (int k = 1; k < n; ++k) {
        int m = n / k;
        if (m * k != n) continue; // Skip if k is not a divisor of n

        Fraction effort(Fraction(1, 1) + Fraction(k, 1) * calculateExpectedTosses(m));
        if (effort < bestEffort) {
            bestEffort = effort;
        }
    }

    memo[n] = bestEffort; // Cache the result
    return bestEffort;
}

int main() {
    int n;
    cin >> n;

    Fraction result = calculateExpectedTosses(n);
    result = simplify(result); // Simplify the fraction

    cout << result.numerator << "/" << result.denominator << endl;
    return 0;
}

