using namespace std;

// Function to count permutations
int count_permutations(const string& str) {
    string s = str;
    sort(s.begin(), s.end());
    int count = 1;
    int n = 1;
    for (int i = 1; i < 6; ++i) {
        if (s[i] == s[i-1]) {
            n++;
        } else {
            count *= n;
            n = 1;
        }
    }
    count *= n;
    return count;
}

// Function to check if two strings are rotations of each other
bool is_rotation(const string& s1, const string& s2) {
    string temp = s1 + s1;
    return temp.find(s2) != string::npos;
}

// Function to generate all rotations of a string
vector<string> get_rotations(const string& str) {
    vector<string> rotations;
    for (int i = 0; i < 6; ++i) {
        rotations.push_back(str.substr(i) + str.substr(0, i));
    }
    return rotations;
}

// Function to generate all faces of a cube
vector<string> get_faces(const string& str) {
    // Define the cube's faces
    vector<string> faces = {
        str.substr(0, 1) + str.substr(1, 1) + str.substr(2, 1) + str.substr(3, 1) + str.substr(4, 1) + str.substr(5, 1),
        str.substr(1, 1) + str.substr(5, 1) + str.substr(0, 1) + str.substr(2, 1) + str.substr(3, 1) + str.substr(4, 1),
        str.substr(2, 1) + str.substr(0, 1) + str.substr(1, 1) + str.substr(4, 1) + str.substr(5, 1) + str.substr(3, 1),
        str.substr(3, 1) + str.substr(4, 1) + str.substr(5, 1) + str.substr(0, 1) + str.substr(1, 1) + str.substr(2, 1),
        str.substr(4, 1) + str.substr(3, 1) + str.substr(5, 1) + str.substr(1, 1) + str.substr(0, 1) + str.substr(2, 1),
        str.substr(5, 1) + str.substr(3, 1) + str.substr(4, 1) + str.substr(2, 1) + str.substr(0, 1) + str.substr(1, 1)
    };
    return faces;
}

int main() {
    string input;
    cin >> input;

    int total_permutations = count_permutations(input);
    vector<string> unique_rotations;

    // Generate all rotations of the input string
    vector<string> rotations = get_rotations(input);

    // Generate all faces of the cube
    vector<string> faces = get_faces(input);

    // Find unique rotations
    for (const auto& rotation : rotations) {
        bool is_unique = true;
        for (const auto& unique_rotation : unique_rotations) {
            if (is_rotation(rotation, unique_rotation)) {
                is_unique = false;
                break;
            }
        }
        if (is_unique) {
            unique_rotations.push_back(rotation);
        }
    }

    // Find unique faces
    vector<string> unique_faces;
    for (const auto& face : faces) {
        bool is_unique = true;
        for (const auto& unique_face : unique_faces) {
            if (is_rotation(face, unique_face)) {
                is_unique = false;
                break;
            }
        }
        if (is_unique) {
            unique_faces.push_back(face);
        }
    }

    // Calculate the number of distinct decorations
    int distinct_decorations = total_permutations / (unique_rotations.size() * unique_faces.size());

    cout << distinct_decorations << endl;

