void rotate(string& s, int times, int axis) {
	vector<char> chars(s.begin(), s.end());
	for (int i = 0; i < times; i++) {
		if (axis == 0) {
			char temp = chars[3];
			chars[3] = chars[2];
			chars[2] = chars[1];
			chars[1] = chars[0];
			chars[0] = temp;
