using namespace std;

map<string, int> cache;

int countPermutations(string s) {
    if (cache.find(s) != cache.end()) return cache[s];

    int permutations = 0;
    if (s.length() == 1) {
        permutations = 1;
    } else {
        for (int i = 0; i < s.length(); ++i) {
            char firstChar = s[i];
            string remaining = s.substr(0, i) + s.substr(i + 1);
            int remainingPermutations = countPermutations(remaining);
            permutations += remainingPermutations;
        }
        int divisor = 1;
        for (char c : "ROYGBV") {
            int count = 0;
            for (char ch : s) if (ch == c) ++count;
            for (int i = 2; i <= count; ++i) divisor *= i;
        }
        permutations /= divisor;
    }

    cache[s] = permutations;
    return permutations;
}

string normalize(const string& s) {
    string minS = s;
    string rotated;
    for (int face = 0; face < 6; ++face) {
        rotated = s;
        for (int _ = 0; _ < face; ++_) {
            char temp = rotated[0];
            for (int i = 0; i < 5; ++i) rotated[i] = rotated[i + 1];
            rotated[5] = temp;
        }
        if (rotated < minS) minS = rotated;
    }
    return minS;
}

int countUniqueDecorations(string s) {
    string normalized = normalize(s);
    map<string, int> uniqueConfigs;
    uniqueConfigs[normalized] = 1;

    int permutations = countPermutations(s);
    int uniqueDecorations = permutations / uniqueConfigs.size();
    return uniqueDecorations;
}

int main() {
    string input;
    cin >> input;

    int result = countUniqueDecorations(input);
    cout << result << endl;

    return 0;
}

