#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

using namespace std;

class Solution {
public:
    int solve(string s) {
        unordered_map<string, int> cache;
        vector<string> axes = {"x", "y", "z"};
        function<int(string, vector<string>)> dfs =
            [&](string state, vector<string> used_axes) {
                if (cache.find(state) != cache.end()) {
                    return cache[state];
                }
                if (used_axes.size() == 3) {
                    return 1;
                }
                int res = 0;
                for (const auto& axis : axes) {
                    if (find(used_axes.begin(), used_axes.end(), axis) ==
                        used_axes.end()) {
                        string next_state = rotate(state, axis);
                        res += dfs(next_state, used_axes);
                    }
                }
                cache[state] = res;
                return res;
            };

        string sorted_state = s;
        sort(sorted_state.begin(), sorted_state.end());
        int total = dfs(s, {});
        int identical = count_permutations(s);
        return total / identical;
    }

    string rotate(string state, string axis) {
        if (axis == "x") {
            return string{state[0], state[3], state[2], state[1], state[4], state[5]};
        } else if (axis == "y") {
            return string{state[5], state[4], state[2], state[0], state[1], state[3]};
        } else { // axis == "z"
            return string{state[1], state[0], state[4], state[5], state[2], state[3]};
        }
    }

    int count_permutations(string s) {
        unordered_map<char, int> cnt;
        for (char c : s) {
            cnt[c]++;
        }
        int res = 6; // 6!
        for (auto& [char_, count] : cnt) {
            res /= factorial(count);
        }
        return res;
    }

    int factorial(int n) {
        int res = 1;
        for (int i = 2; i <= n; ++i) {
            res *= i;
        }
        return res;
    }
};

int main() {
    string s;
    cin >> s;
    Solution solution;
    cout << solution.solve(s) << endl;
    return 0;
}

