    }
};

struct SparseTable {
    vector<vector<int>> table;

    SparseTable(vector<int>& arr) {
        int n = arr.size();
        int maxLog = log2(n) + 1;
        table.resize(n, vector<int>(maxLog));
        for (int i = 0; i < n; i++) {
            table[i][0] = arr[i];
        }
        for (int j = 1; j < maxLog; j++) {
            for (int i = 0; i + (1 << j) <= n; i++) {
                table[i][j] = min(table[i][j - 1], table[i + (1 << (j - 1))][j - 1]);
            }
        }
    }

