#include <iostream>
#include <vector>
#include <algorithm>

struct Ring {
    int a, b, h;
};

bool cmp(const Ring& a, const Ring& b) {
    if (a.b == b.b) return a.a > b.a;
    return a.b < b.b;
}

int main() {
    int n;
    std::cin >> n;

    std::vector<Ring> rings(n);
    for (auto& ring : rings) {
        std::cin >> ring.a >> ring.b >> ring.h;
    }

    std::sort(rings.begin(), rings.end(), cmp);

    std::vector<int> dp(n);
    int max_height = 0;

    for (int i = 0; i < n; ++i) {
        dp[i] = rings[i].h;
        for (int j = 0; j < i; ++j) {
            if (rings[j].a < rings[i].b && rings[j].b >= rings[i].a) {
                dp[i] = std::max(dp[i], dp[j] + rings[i].h);
            }
        }
        max_height = std::max(max_height, dp[i]);
    }

    std::cout << max_height << std::endl;

    return 0;
}

