ll a[MAX_N], b[MAX_N], h[MAX_N];

struct SegTree {
    int size;
    vector<ll> data;

    void init(int _size) {
        size = _size;
        data.resize(2 * size);
    }

    void update(int idx, ll val) {
        idx += size;
        data[idx] = val;
        while (idx > 1) {
            idx >>= 1;
            data[idx] = max(data[2*idx], data[2*idx+1]);
        }
    }

    ll query(int l, int r) {
        l += size, r += size;
        ll res = 0;
        while (l <= r) {
            if (l & 1) res = max(res, data[l++]);
            if (!(r & 1)) res = max(res, data[r--]);
            l >>= 1, r >>= 1;
        }
        return res;
    }
};

