int minDeletions(const std::string& n, int k) {
    int power = k;
    int divisor = 10;
    while (power-- > 1) divisor *= 10;

    int minLength = n.length();
    for (int i = 0; i < (1 << n.length()); ++i) {
        std::string num;
        for (int j = 0; j < n.length(); ++j) {
            if (i & (1 << j)) num += n[j];
        }
        if (num.empty() || (num.length() > 1 && num[0] == '0')) continue;
        int number = std::stoi(num);
        if (number % divisor == 0) minLength = std::min(minLength, (int)n.length() - (int)num.length());
    }
    return minLength;
}

