using namespace std;

long long max_f = 0;

void calculate_max_f(vector<long long>& a, int l, int r) {
    long long sum = 0;
    for (int i = l; i < r; i++) {
        sum += a[i];
    }
    max_f = max(max_f, sum);
    max_f = max(max_f, abs(sum - 2 * a[l]));
    max_f = max(max_f, abs(sum - 2 * a[r-1]));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<long long> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    for (int l = 0; l < n - 1; l++) {
        for (int r = l + 2; r <= n; r++) {
            calculate_max_f(a, l, r);
        }
    }

    for (int i = 0; i < n - 1; i++) {
        max_f = max(max_f, abs(a[i] - a[i+1]));
    }

    cout << max_f << endl;

    return 0;
}

