#include <iostream>
#include <vector>
#include <climits>

long long max_absolute_difference(const std::vector<int>& a, int l, int r) {
    int min_val = INT_MAX;
    int max_val = INT_MIN;
    for (int i = l; i < r; ++i) {
        min_val = std::min(min_val, a[i]);
        max_val = std::max(max_val, a[i]);
    }
    return max_val - min_val;
}

int main() {
    int n;
    std::cin >> n;

    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    long long max_diff = 0;
    for (int l = 0; l < n - 1; ++l) {
        for (int r = l + 2; r <= n; ++r) {
            max_diff = std::max(max_diff, max_absolute_difference(a, l, r));
        }
    }

    std::cout << max_diff << std::endl;
    return 0;
}

