using namespace std;

string generateName(int i) {
    string names = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    string name = "";
    name += names[i % 26];
    int j = i / 26;
    while (j > 0) {
        name += 'a' + (j - 1) % 26;
        j = (j - 1) / 26;
    }
    return name;
}

