    return lhs.price < rhs.price;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> p(n);
    for (auto& x : p) cin >> x;

    vector<int> a(n), b(n);
    for (auto& x : a) cin >> x;
    for (auto& x : b) cin >> x;

    vector<Shirt> shirts;
    for (int i = 0; i < n; ++i) {
        shirts.emplace_back(p[i], a[i], b[i]);
    }

    sort(shirts.begin(), shirts.end(), cmp);

    vector<vector<Shirt>> color_groups(4); // 1-3, ignore index 0
    for (const auto& shirt : shirts) {
        if (shirt.a == shirt.b) {
            color_groups[shirt.a].push_back(shirt);
        } else {
            color_groups[shirt.a].push_back(shirt);
            color_groups[shirt.b].push_back(shirt);
        }
    }

    vector<int> c;
