using namespace std;

#define int long long
#define endl '\n'

const int INF = 1e18;

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> p(n);
    for (auto& x : p) {
        cin >> x;
    }

    vector<int> a(n);
    for (auto& x : a) {
        cin >> x;
    }

    vector<int> b(n);
    for (auto& x : b) {
        cin >> x;
    }

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> q[4];

    for (int i = 0; i < n; ++i) {
        q[a[i]].push({p[i], i});
        q[b[i]].push({p[i], i});
    }

    int m;
    cin >> m;

    vector<int> c(m);
    for (auto& x : c) {
        cin >> x;
    }

    vector<bool> used(n, false);

    vector<int> res(m);

    for (int i = 0; i < m; ++i) {
        int color = c[i];
        int min_price = INF;
        int idx = -1;

        while (!q[color].empty()) {
            auto [price, cur_idx] = q[color].top();
            q[color].pop();

            if (!used[cur_idx]) {
                min_price = price;
                idx = cur_idx;
                break;
            }
        }

        if (idx == -1) {
            res[i] = -1;
        } else {
            used[idx] = true;
            res[i] = min_price;
        }
    }

    for (auto& x : res) {
        cout << x << " ";
    }
    cout << endl;
}

