#include <algorithm>

using namespace std;

struct Shirt {
    long long price;
    int front;
    int back;
    bool taken = false;
};

bool compareShirts(const Shirt& a, const Shirt& b) {
    return a.price < b.price;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Shirt> shirts(n);
    for (int i = 0; i < n; ++i) {
        cin >> shirts[i].price;
    }
    for (int i = 0; i < n; ++i) {
        cin >> shirts[i].front;
    }
    for (int i = 0; i < n; ++i) {
        cin >> shirts[i].back;
    }

    sort(shirts.begin(), shirts.end(), compareShirts);

    int m;
    cin >> m;

    vector<int> c(m);
    for (int i = 0; i < m; ++i) {
        cin >> c[i];
    }

    vector<long long> result(m, -1);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!shirts[j].taken && (shirts[j].front == c[i] || shirts[j].back == c[i])) {
                result[i] = shirts[j].price;
                shirts[j].taken = true;
                break;
            }
        }
    }

    for (long long price : result) {
        cout << price << " ";
    }
    cout << endl;

    return 0;
}

