#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

double calculateChiSquare(const vector<int>& data, int P, bool isPoisson) {
    double chiSquare = 0.0;
    int expectedCounts[1001] = {0}; // Assuming max value is 1000

    if (isPoisson) {
        for (int k = 0; k <= 1000; ++k) {
            double probability = (pow(P, k) * exp(-P)) / tgamma(k + 1);
            expectedCounts[k] = probability * 250;
        }
    } else {
        for (int k = 0; k <= 2 * P; ++k) {
            expectedCounts[k] = 250 / (2 * P + 1);
        }
    }

    int observedCounts[1001] = {0};
    for (int val : data) {
        observedCounts[val]++;
    }

    for (int k = 0; k <= 1000; ++k) {
        if (expectedCounts[k] > 0) {
            chiSquare += pow(observedCounts[k] - expectedCounts[k], 2) / expectedCounts[k];
        }
    }

    return chiSquare;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int V;
    cin >> V;

    for (int village = 0; village < V; ++village) {
        vector<int> data(250);
        for (int& val : data) {
            cin >> val;
        }

        int maxVal = *max_element(data.begin(), data.end());
        int PGuess = maxVal / 2; // Initial guess for P

        // Refine PGuess for uniform distribution
        while (PGuess < maxVal) {
            PGuess++;
        }
        PGuess /= 2; // Adjust after loop

        double poissonChiSquare = calculateChiSquare(data, PGuess, true);
        double uniformChiSquare = calculateChiSquare(data, PGuess, false);

        if (poissonChiSquare < uniformChiSquare) {
            cout << "poisson\n";
        } else {
            cout << "uniform\n";
        }
    }

    return 0;
}

