using namespace std;

double poisson_likelihood(const vector<int>& data, int p) {
    double likelihood = 0.0;
    for (int k : data) {
        double prob = (pow(p, k) * exp(-p)) / tgamma(k + 1);
        likelihood += log(prob);
    }
    return likelihood;
}

double uniform_likelihood(const vector<int>& data, int p) {
    int max_k = *max_element(data.begin(), data.end());
    if (max_k > 2 * p) {
        return -1e18; // very low likelihood
    }
    double likelihood = -250 * log(2 * p + 1);
    return likelihood;
}

