#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

double calculateChiSquare(const vector<int>& data, int p) {
    double chiSquare = 0.0;
    double expected;

    for (int k = 0; k <= 2 * p; ++k) {
        if (k <= p) {
            expected = 250 * exp(-p) * pow(p, k) / tgamma(k + 1);
        } else {
            expected = 250 / (2 * p + 1);
        }

        double residual = 0.0;
        for (const auto& d : data) {
            if (d == k) {
                ++residual;
            }
        }

        if (expected > 0) {
            chiSquare += pow(residual - expected, 2) / expected;
        }
    }

    return chiSquare;
}

double calculateChiSquareUniform(const vector<int>& data, int p) {
    double chiSquare = 0.0;
    double expected = 250.0 / (2 * p + 1);

    for (int k = 0; k <= 2 * p; ++k) {
        double residual = 0.0;
        for (const auto& d : data) {
            if (d == k) {
                ++residual;
            }
        }

        if (expected > 0) {
            chiSquare += pow(residual - expected, 2) / expected;
        }
    }

    return chiSquare;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int v;
    cin >> v;

    for (int i = 0; i < v; ++i) {
        vector<int> data(250);
        for (auto& d : data) {
            cin >> d;
        }

        int p = *max_element(data.begin(), data.end()) + 1; // Initial guess for p
        double minChiSquarePoisson = calculateChiSquare(data, p);
        double minChiSquareUniform = calculateChiSquareUniform(data, p);

        // Refine p for Poisson
        for (int newP = max(10, p - 10); newP <= p + 10; ++newP) {
            if (newP < 10) continue; // As per problem statement
            double chiSquare = calculateChiSquare(data, newP);
            if (chiSquare < minChiSquarePoisson) {
                minChiSquarePoisson = chiSquare;
                p = newP;
            }
        }

        // Refine p for Uniform
        for (int newP = max(10, p - 10); newP <= p + 10; ++newP) {
            if (newP < 10) continue; // As per problem statement
            double chiSquare = calculateChiSquareUniform(data, newP);
            if (chiSquare < minChiSquareUniform) {
                minChiSquareUniform = chiSquare;
                p = newP;
            }
        }

        if (minChiSquarePoisson < minChiSquareUniform) {
            cout << "poisson" << endl;
        } else {
            cout << "uniform" << endl;
        }
    }

    return 0;
}

