double chiTest(const vector<int>& data, double (*func)(int, double), double param) {
    double chi2 = 0.0;
    int n = data.size();
    int maxK = *max_element(data.begin(), data.end());

    vector<double> expected(n, 0.0);
    for (int k = 0; k <= maxK; ++k) {
        double prob = func(k, param);
        expected[k] = prob * n;
    }

    for (int k = 0; k <= maxK; ++k) {
        int observed = count(data.begin(), data.end(), k);
        if (expected[k] > 0) {
            chi2 += pow(observed - expected[k], 2) / expected[k];
        }
    }

    return chi2;
}

