double calculateChiSquare(const vector<int>& data, const vector<double>& probabilities) {
    double chiSquare = 0.0;
    int n = data.size();
    for (int i = 0; i < probabilities.size(); ++i) {
        double expected = n * probabilities[i];
        double actual = 0.0;
        for (int j = 0; j < n; ++j) {
            if (data[j] == i) {
                actual += 1.0;
            }
        }
        chiSquare += pow(actual - expected, 2) / expected;
    }
    return chiSquare;
}

