#include <bits/stdc++.h>
using namespace std;

class Marmot {
public:
    long long count;
    long long sum;
    Marmot() {
        count = 0;
        sum = 0;
    }
    void add(int x) {
        count++;
        sum += x;
    }
    double avg() {
        if (count == 0) return 0;
        return (double)sum / count;
    }
    double var() {
        if (count < 2) return 0;
        double avgVal = avg();
        double sumSq = 0;
        sumSq += (sum - avgVal * count) * (sum - avgVal * count);
        for (int i = 0; i < count - 1; i++) {
            sumSq += (avgVal * (i + 1) - avgVal * i) * (avgVal * (i + 1) - avgVal * i);
        }
        return sumSq / count;
    }
};

