double mean(const vector<int>& samples) {
    double sum = 0.0;
    for (int sample : samples) {
        sum += sample;
    }
    return sum / samples.size();
}

double variance(const vector<int>& samples) {
    double m = mean(samples);
    double sum_sq_diff = 0.0;
    for (int sample : samples) {
        sum_sq_diff += pow(sample - m, 2);
    }
    return sum_sq_diff / samples.size();
}

int estimate_population(const vector<int>& samples) {
    double mean_samples = mean(samples);
    double variance_samples = variance(samples);

    if (abs(mean_samples - variance_samples) < 1e-6) { // Poisson distribution
        return round(mean_samples);
    } else { // Uniform distribution
        int max_sample = *max_element(samples.begin(), samples.end());
        return round((max_sample + 1) / 2.0);
    }
}

