#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

class Prob {
public:
    vector<int> villagePopulation;
    int numberOfVillages;
    vector<vector<int>> marmotAnswers;

    Prob() {
        readInput();
    }

    void readInput() {
        cin >> numberOfVillages;
        villagePopulation.resize(numberOfVillages);
        marmotAnswers.resize(numberOfVillages);

        for (int i = 0; i < numberOfVillages; i++) {
            int numMarmots;
            cin >> numMarmots;
            marmotAnswers[i].resize(numMarmots);
            for (int j = 0; j < numMarmots; j++) {
                cin >> marmotAnswers[i][j];
            }
        }
    }

    void solve() {
        for (int i = 0; i < numberOfVillages; i++) {
            int sum = 0;
            for (int ans : marmotAnswers[i]) {
                sum += ans;
            }
            int avg = sum / marmotAnswers[i].size();
            int variance = 0;
            for (int ans : marmotAnswers[i]) {
                variance += (ans - avg) * (ans - avg);
            }
            variance /= marmotAnswers[i].size();

            if (abs(avg - variance) < 1e-9) {
                // Poisson distribution
                villagePopulation[i] = avg;
            } else {
                // Uniform distribution
                int minAns = *min_element(marmotAnswers[i].begin(), marmotAnswers[i].end());
                int maxAns = *max_element(marmotAnswers[i].begin(), marmotAnswers[i].end());
                villagePopulation[i] = (minAns + maxAns) / 2;
            }
        }
    }

    void writeOutput() {
        for (int pop : villagePopulation) {
            cout << pop << endl;
        }
    }
};

int main() {
    Prob prob;
    prob.solve();
    prob.writeOutput();
    return 0;
}

