double calculateChiSquare(const vector<double>& observed, const vector<double>& expected) {
    double chiSquare = 0.0;
    for (size_t i = 0; i < observed.size(); ++i) {
        if (expected[i] > 0) {
            double diff = observed[i] - expected[i];
            chiSquare += diff * diff / expected[i];
        }
    }
    return chiSquare;
}

