bool isUniform(const std::vector<int>& samples, int P) {
    int minVal = *std::min_element(samples.begin(), samples.end());
    int maxVal = *std::max_element(samples.begin(), samples.end());

    if (maxVal - minVal > 2 * P) return false;

    std::vector<int> expected(P * 2 + 1, 0);
    for (int& sample : samples) {
        if (sample < -P || sample > P) return false;
        expected[sample + P]++;
    }

    int count = samples.size();
    double avg = count / double(2 * P + 1);
    for (double val : expected) {
        if (std::abs(val - avg) > std::sqrt(avg)) return false;
    }

    return true;
}

bool isPoisson(const std::vector<int>& samples, int P) {
    int lambda = 0;
    for (int sample : samples) lambda += (sample + P);

    lambda /= samples.size();

    if (lambda < 0) return false;

    double sum = 0.0;
    for (int k = 0; k < samples.size(); ++k) {
        double prob = (pow(lambda, k) * exp(-lambda)) / tgamma(k + 1);
        sum += prob;
    }

    double threshold = 1e-6;
    if (std::abs(sum - 1.0) < threshold) return true;

    return false;
}

