bool solve(int n, const vector<long long>& a) {
    long long total = 0;
    for (long long x : a) total += x;

    if (total % 2 != 0) return false;

    long long target = total / 2;
    long long current = 0;

    for (long long x : a) {
        current += x;
        if (current == target) return true;
        if (current > target) return false;
    }

    vector<long long> prefix_sums(n);
    prefix_sums[0] = a[0];
    for (int i = 1; i < n; ++i) prefix_sums[i] = prefix_sums[i-1] + a[i];

    for (int i = 0; i < n; ++i) {
        long long without = prefix_sums.back() - a[i];
        if (without == target * 2) return true;

        long long remaining = total - a[i];
        if (remaining % 2 != 0) continue;

        target = remaining / 2;
        current = 0;

        for (int j = 0; j < n; ++j) {
            if (j == i) continue;
            current += a[j];
            if (current == target) return true;
            if (current > target) break;
        }
    }

    return false;
}

