bool canMakeNonIncreasing(const vector<int>& a, const vector<int>& b) {
    int zeros = count(a.begin(), a.end(), 0);
    if (zeros != b.size()) return false; // Sanity check (guaranteed by problem statement)

    // Try all permutations of b
    vector<int> bPerm = b;
    sort(bPerm.begin(), bPerm.end()); // Start with sorted to check increasing case first
    do {
        vector<int> aCopy = a;
        int bIdx = 0;
        for (int i = 0; i < aCopy.size(); ++i) {
            if (aCopy[i] == 0) {
