        for (int i = 1; i < aCopy.size(); ++i) {
            if (aCopy[i] <= aCopy[i-1]) {
                isNotIncreasing = true;
                break;
            }
        }
        if (isNotIncreasing) return true; // Found a valid permutation
    } while (next_permutation(bPerm.begin(), bPerm.end()));

