using namespace std;

bool can_recover(const vector<int>& a, const vector<int>& b) {
    vector<int> zeros;
    for (int i = 0; i < a.size(); ++i) {
        if (a[i] == 0) {
            zeros.push_back(i);
        }
    }

    auto is_increasing = [](const vector<int>& seq) {
        for (int i = 1; i < seq.size(); ++i) {
            if (seq[i] < seq[i - 1]) {
                return false;
            }
        }
        return true;
    };

    vector<bool> used(b.size(), false);
    function<bool(int)> backtrack = [&](int idx) {
        if (idx == zeros.size()) {
            return !is_increasing(a);
        }

        for (int i = 0; i < b.size(); ++i) {
            if (!used[i]) {
                auto seq = a;
                seq[zeros[idx]] = b[i];
                used[i] = true;

                if (backtrack(idx + 1)) {
                    return true;
                }

                used[i] = false;
            }
        }

        return false;
    };

    return backtrack(0);
}

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    for (auto& x : a) {
        cin >> x;
    }

    vector<int> b(k);
    for (auto& x : b) {
        cin >> x;
    }

