using namespace std;

void permute(int n, int m, const vector<int>& l) {
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        a[i] = 1;
    }

    for (int k = 0; k < m - 1; ++k) {
        int i = l[k] - 1;
        int j = l[k + 1] - 1;
        int dist = (j - i + n) % n;
        if (dist <= 0 || dist >= n) {
            cout << -1 << endl;
            return;
        }
        a[i] = dist;
    }

    for (int i = 0; i < m - 1; ++i) {
        int i_curr = l[i] - 1;
        int next_leader = (i_curr + a[i_curr]) % n;
        if (next_leader == 0) next_leader = n;
        if (l[i + 1] - 1 != next_leader - 1) {
            cout << -1 << endl;
            return;
        }
    }

    for (int i : a) {
        cout << i << " ";
    }
    cout << endl;
}

