    if (n % 2 == 1) {
        // Handle odd n
        for (int i = 1; i <= n - 1; i++) {
            cycles.push_back({i, i + 1, n});
            cycles.push_back({i, n, i + 1});
        }
        // Add a 4-cycle for the last edge
        cycles.push_back({1, 2, 3, n});
        cycles.push_back({1, 3, 2, n});
    } else {
        // Handle even n
        for (int i = 1; i <= n - 1; i++) {
            cycles.push_back({i, i + 1, n});
            cycles.push_back({i, n, i + 1});
        }
        // Add two 4-cycles for the last edge
        cycles.push_back({1, 2, 3, n});
        cycles.push_back({1, 3, 2, n});
    }

    cout << cycles.size() << endl;
    for (const auto& cycle : cycles) {
