class SegmentTree {
public:
    struct Node {
        int minCost;
        Node() : minCost(1e18) {}
    };
    int n;
    vector<Node> tree;
    SegmentTree(int _n) : n(_n), tree(4 * _n) {}
    void update(int pos, int val, int node = 1, int nl = 0, int nr = -1) {
        if (nr == -1) nr = n - 1;
        if (nl == nr) {
            tree[node].minCost = min(tree[node].minCost, val);
            return;
        }
        int mid = (nl + nr) / 2;
        if (pos <= mid) update(pos, val, node * 2, nl, mid);
        else update(pos, val, node * 2 + 1, mid + 1, nr);
        tree[node].minCost = min(tree[node * 2].minCost, tree[node * 2 + 1].minCost);
    }
    int query(int l, int r, int node = 1, int nl = 0, int nr = -1) {
        if (nr == -1) nr = n - 1;
        if (r < nl || l > nr) return 1e18;
        if (l <= nl && nr <= r) return tree[node].minCost;
        int mid = (nl + nr) / 2;
        return min(query(l, r, node * 2, nl, mid), query(l, r, node * 2 + 1, mid + 1, nr));
    }
};

