#include <bits/stdc++.h>
using namespace std;

class SegmentTree {
public:
    vector<int> tree;
    vector<int> arr;
    int n;

    SegmentTree(vector<int>& arr) {
        this->arr = arr;
        n = arr.size();
        tree.resize(4 * n);
        buildTree(0, n - 1, 0);
    }

    void buildTree(int start, int end, int node) {
        if (start == end) {
            tree[node] = arr[start];
            return;
        }
        int mid = (start + end) / 2;
        buildTree(start, mid, 2 * node + 1);
        buildTree(mid + 1, end, 2 * node + 2);
        tree[node] = min(tree[2 * node + 1], tree[2 * node + 2]);
    }

    int queryTree(int start, int end, int node, int left, int right) {
        if (start > right || end < left) return INT_MAX;
        if (start >= left && end <= right) return tree[node];
        int mid = (start + end) / 2;
        return min(queryTree(start, mid, 2 * node + 1, left, right),
                   queryTree(mid + 1, end, 2 * node + 2, left, right));
    }

    int query(int left, int right) {
        return queryTree(0, n - 1, 0, left, right);
    }
};

int main() {
